// Shared "Domains" quick-reference for Cleric — a "Domains" button (matches the
// plain-text style of neighboring toolbar buttons) that opens a dropdown of every
// official Pathfinder 1e cleric domain and subdomain (copied verbatim from Archives
// of Nethys via the Core Rulebook + supplements), each showing its granted powers and
// its 9-level domain spell list. Purely a reference panel -- it doesn't tie into a
// character's own domain1/domain2 selection (that mechanism already exists
// separately on the Universal Cleric Sheet); this is for browsing/looking things up.
(function (global) {
  const DOMAINS = {"Artifice":{"grantedPowers":[{"name":"Artificer's Touch","type":"Sp","level":1,"text":"You can cast mending at will, using your cleric level as the caster level to repair damaged objects. In addition, you can cause damage to objects and construct creatures by striking them with a melee touch attack. Objects and constructs take 1d6 points of damage +1 for every two cleric levels you possess. This attack bypasses an amount of damage reduction and hardness equal to your cleric level. You can use this ability a number of times per day equal to 3 + your Wisdom modifier."},{"name":"Dancing Weapons","type":"Su","level":8,"text":"At 8th level, you can give a weapon touched the dancing special weapon quality for 4 rounds. You can use this ability once per day at 8th level, and an additional time per day for every four levels beyond 8th."}],"domainSpells":{"1":"Animate Rope","2":"Wood Shape","3":"Stone Shape","4":"Minor Creation","5":"Fabricate","6":"Major Creation","7":"Wall of Iron","8":"Statue","9":"Prismatic Sphere"},"subdomainNames":["Alchemy","Construct","Industry","Toil","Trap"],"subdomains":{"Alchemy":{"grantedPowers":[{"name":"Divine Alchemy","type":"Su","level":1,"text":"You can perform a 1-minute ritual that infuses a flask of water with one of your prepared spells, creating an improvised potion that lasts until consumed or the next time you prepare spells. You can use this ability only with spells that target one or more creatures, and the maximum spell level you can infuse in this way is equal to 1 + 1 for every 4 cleric levels you have. These potions are treated as alchemist extracts for the purpose of your domain spells. You can use this ability a number of times per day equal to 3 + your Wisdom modifier."}],"domainSpells":{}},"Construct":{"grantedPowers":[{"name":"Animate Servant","type":"Su","level":8,"text":"At 8th level, as a standard action, you can give life to inanimate objects. This ability functions as animate objects using your cleric level as the caster level. You can use this ability once per day at 8th level, and one additional time per day for every four levels beyond 8th."}],"domainSpells":{}},"Industry":{"grantedPowers":[{"name":"Aura of Efficiency","type":"Su","level":8,"text":"At 8th level, you can emit a 30-foot-radius aura that grants your allies a +4 bonus on all saving throws against effects that inflict the fatigued or exhausted condition. Any equipment wielded by your allies within this area gets a bonus to hardness equal to 1/2 your cleric level, and your allies' attacks against targets within this area ignore an equal amount of hardness. You can use this aura for a number of rounds per day equal to your cleric level. These rounds do not need to be consecutive."}],"domainSpells":{}},"Toil":{"grantedPowers":[{"name":"Aura of Repetition","type":"Su","level":8,"text":"At 8th level, you can emit a 30-foot aura of repetition for a number of rounds per day equal to your cleric level. All enemies within this aura must make a Will save each round or repeat their action from the previous round (if possible). Creatures that attacked on the previous round attack again on the following round, although they may change their target. Creatures that moved the previous round must take the same move action again, although they may change their route. Creatures that drank a potion must do so again, even they can only drink from an empty bottle. Actions that cannot be repeated are wasted. These rounds do not need to be consecutive."}],"domainSpells":{}},"Trap":{"grantedPowers":[{"name":"Supernatural Trap","type":"Su","level":8,"text":"At 8th level, select a supernatural ranger trap (Pathfinder RPG Ultimate Magic 64). You can use this trap a number of times per day equal to your Wisdom bonus. The DCs for Perception checks, Disable Device checks, and saving throws against the trap are equal to 10 + 1/2 your character level + your Wisdom bonus. The trap lasts for 1 hour or until triggered."}],"domainSpells":{}}}},"Chaos":{"grantedPowers":[{"name":"Touch of Chaos","type":"Sp","level":1,"text":"You can imbue a target with chaos as a melee touch attack. For the next round, anytime the target rolls a d20, he must roll twice and take the less favorable result. You can use this ability a number of times per day equal to 3 + your Wisdom modifier."},{"name":"Chaos Blade","type":"Su","level":8,"text":"At 8th level, you can give a weapon touched the anarchic special weapon quality for a number of rounds equal to 1/2 your cleric level. You can use this ability once per day at 8th level, and an additional time per day for every four levels beyond 8th."}],"domainSpells":{"1":"Protection from Law","2":"Align Weapon (chaos only)","3":"Magic Circle against Law","4":"Chaos Hammer","5":"Dispel Law","6":"Animate Objects","7":"Word of Chaos","8":"Cloak of Chaos","9":"Summon Monster IX (chaos spell only)"},"subdomainNames":["Azata","Demodand","Demon","Entropy","Protean","Revelry","Riot","Whimsy"],"subdomains":{"Azata":{"grantedPowers":[{"name":"Elysium's Call","type":"Su","level":1,"text":"With a touch, you can imbue creatures with the spirit of Elysium, lifting their spirits and freeing them from bonds. The creatures touched can immediately reroll any failed saving throws against spells and spell-like abilities of the enchantment (charm) and enchantment (compulsion) subschools. In addition, targets receive a +2 sacred bonus on such saving throws and a +2 sacred bonus on CMB checks to escape a grapple. Finally, targets can ignore up to 5 feet of difficult terrain each round, as if they had the Nimble Moves feat. These bonuses last for a number of rounds equal to 1/2 your cleric level (minimum 1), although the saving throw reroll only applies when the creature is touched. You can use this ability for a number of rounds per day equal to 3 + your Wisdom modifier."}],"domainSpells":{}},"Demodand":{"grantedPowers":[{"name":"Faith-Stealing Strike","type":"Su","level":1,"text":"You can make a single melee attack using your highest base attack bonus against a creature capable of casting divine spells. If you damage the creature, it must succeed at a Will save (DC = 10 + 1/2 your cleric level + your Wisdom modifier) or be unable to cast any divine spells for 1 round. If you do not damage your target with the attack, this ability is expended with no effect. You can use this ability a number of times per day equal to 3 + your Wisdom modifier."}],"domainSpells":{}},"Demon":{"grantedPowers":[{"name":"Fury of the Abyss","type":"Su","level":1,"text":"As a swift action, you can give yourself an enhancement bonus equal to 1/2 your cleric level (minimum +1) on melee attacks, melee damage rolls, and combat maneuver checks. This bonus lasts for 1 round. During this round, you take a –2 penalty to AC. You can use this ability for a number of times per day equal to 3 + your Wisdom modifier."}],"domainSpells":{}},"Entropy":{"grantedPowers":[{"name":"Hasten the End","type":"Su","level":8,"text":"At 8th level, as an immediate action upon successfully hitting an opponent with a melee attack, you reduce the remaining duration of all beneficial magical effects currently affecting the target by 1 round, minute, hour, or day—whichever measurement is used to determine the duration of each particular magical effect. You can use this ability once per day at 8th level, and an additional time per day for every 4 levels beyond 8th."}],"domainSpells":{}},"Protean":{"grantedPowers":[{"name":"Aura of Chaos","type":"Su","level":8,"text":"At 8th level, you can surround yourself with a field wild energies. Thee energies manifest as a 30-foot aura of chaos for a number of rounds per day equal to your cleric level. All enemies within this aura must declare one type of action at the start of their turn (attack, cast a spell, move, use an item, or activate a special ability) and make a Will save. Creatures that fail the Will save must take an action other than their declared action. If they succeed, they must take the declared action. Creatures cannot select actions that they cannot perform."}],"domainSpells":{}},"Revelry":{"grantedPowers":[{"name":"Intense Celebration","type":"Su","level":8,"text":"At 8th level, spells you cast that confer a morale effect upon you or your allies are automatically affected as if by the Extend Spell metamagic feat, but with no increase in spell level."}],"domainSpells":{}},"Riot":{"grantedPowers":[{"name":"Aura of Bedlam","type":"Su","level":8,"text":"At 8th level, you can emit a 30-foot-radius aura of chaos and strife for 1 round per cleric level. Enemies in the aura take a –4 penalty on concentration checks and are treated as experiencing vigorous motion (concentration DC = 10 + spell level) when attempting to cast spells. This penalty increases by 1 for every 2 cleric levels you have beyond 8th. This is a mind-affecting effect. These rounds need not be consecutive."}],"domainSpells":{}},"Whimsy":{"grantedPowers":[{"name":"Unexpected Whimsy","type":"Su","level":8,"text":"As a standard action, you dance, act like a buffoon, or commit some other act of whimsy. When you do, enemies within 30 feet of you that can see and hear you must succeed a Will saving throw (DC = 10 + 1/2 your cleric level + half your Wisdom modifier) or they collapse into gales of manic laughter, falling prone. Those who fail their saving throws can take no actions other than laughing for 1 round, but are not considered helpless. You can use this ability once per day at 8th level and one additional time for every 4 levels you possess beyond 8th."}],"domainSpells":{}}}},"Charm":{"grantedPowers":[{"name":"Dazing Touch","type":"Sp","level":1,"text":"You can cause a living creature to become dazed for 1 round as a melee touch attack. Creatures with more Hit Dice than your cleric level are unaffected. You can use this ability a number of times per day equal to 3 + your Wisdom modifier."},{"name":"Charming Smile","type":"Sp","level":8,"text":"At 8th level, you can cast charm person as a swift action, with a DC of 10 + 1/2 your cleric level + your Wisdom modifier. You can only have one creature charmed in this way at a time. The total number of rounds of this effect per day is equal to your cleric level. The rounds do not need to be consecutive, and you can dismiss the charm at any time as a free action. Each attempt to use this ability consumes 1 round of its duration, whether or not the creature succeeds on its save to resist the effect."}],"domainSpells":{"1":"Charm Person","2":"Calm Emotions","3":"Suggestion","4":"Heroism","5":"Charm Monster","6":"Geas/Quest","7":"Insanity","8":"Demand","9":"Dominate Monster"},"subdomainNames":["Captivation","Love","Lust"],"subdomains":{"Captivation":{"grantedPowers":[{"name":"Entrancing Aura","type":"Su","level":8,"text":"At 8th level, you can emit an imperceptible 30-foot aura of distraction as a standard action for a number of rounds equal to your cleric level. These rounds need not be consecutive. Enemies within this aura take a –5 penalty on Perception checks and are treated as though they had 2 fewer Hit Dice (minimum 1 Hit Die) for the purpose of your effects that would give them the fascinated condition. At 16th level, they are instead treated as if they had 3 fewer Hit Dice for such effects."}],"domainSpells":{}},"Love":{"grantedPowers":[{"name":"Adoration","type":"Su","level":1,"text":"As an immediate action, you can attempt to thwart a melee or ranged attack that targets you. This ability functions as sanctuary, but only against one individual attack. You must use the ability after the attack is declared but before the roll is made. The creature attacking you receives a Will save to negate this effect. If a creature has more than one attack, this ability only affects one of the attacks. You can use the ability a number of times per day equal to 3 + your Wisdom modifier. This is a mind-affecting effect."}],"domainSpells":{}},"Lust":{"grantedPowers":[{"name":"Anything to Please","type":"Su","level":8,"text":"At 8th level, you can compel a creature within 30 feet to attempt to please you as a standard action. The creature receives a Will save to negate this affect. If the save fails, the creature attacks your enemies for 1 round, gives you its most valuable item, or drops prone at your feet and grovels for 1d4 rounds (GM’s choice). You can use this ability once per day at 8th level and one additional time per day for every four levels beyond 8th. This is a mind-affecting effect."}],"domainSpells":{}}}},"Community":{"grantedPowers":[{"name":"Calming Touch","type":"Sp","level":1,"text":"You can touch a creature as a standard action to heal it of 1d6 points of nonlethal damage + 1 point per cleric level. This touch also removes the fatigued, shaken, and sickened conditions (but has no effect on more severe conditions). You can use this ability a number of times per day equal to 3 + your Wisdom modifier."},{"name":"Unity","type":"Su","level":8,"text":"At 8th level, whenever a spell or effect targets you and one or more allies within 30 feet, you can use this ability to allow your allies to use your saving throw against the effect in place of their own. Each ally must decide individually before the rolls are made. Using this ability is an immediate action. You can use this ability once per day at 8th level, and one additional time per day for every four cleric levels beyond 8th."}],"domainSpells":{"1":"Bless","2":"Shield Other","3":"Prayer","4":"Imbue with Spell Ability","5":"Telepathic Bond","6":"Heroes' Feast","7":"Refuge","8":"Mass Cure Critical Wounds","9":"Miracle"},"subdomainNames":["Cooperation","Education","Family","Home"],"subdomains":{"Cooperation":{"grantedPowers":[{"name":"Synergistic Touch","type":"Sp","level":1,"text":"You can touch a creature as a standard action to confer upon it the benefits of any one Teamwork feat that you possess. This effect persists for a number of rounds equal to 1/2 your cleric level (minimum 1). You can use this ability a number of times per day equal to 3 + your Wisdom modifier."}],"domainSpells":{}},"Education":{"grantedPowers":[{"name":"Teaching Moment","type":"Su","level":8,"text":"At 8th level, when you or an ally within 30 feet rolls a natural 1 or a natural 20 on an attack roll, an ability check, a skill check, or a saving throw, as an immediate action you can grant all allies within 30 feet special insights that help them overcome similar challenges. Once during the next minute, each affected creature can choose to roll twice and take the better result before attempting an attack roll, ability check, skill check, or saving throw. You can use this ability once per day at 8th level, and one additional time per day for every 4 cleric levels beyond 8th."}],"domainSpells":{}},"Family":{"grantedPowers":[{"name":"Binding Ties","type":"Su","level":1,"text":"As a standard action, you can touch an ally and remove one condition affecting the ally by transferring it to yourself. This transfer lasts a number of rounds equal to your cleric level, but you can end it as a free action on your turn. At the end of this effect, the condition reverts to the original creature, unless it has ended or is removed by another effect. While this power is in use, the target is immune to the transferred condition. You can use this ability a number of times per day equal to 3 + your Wisdom modifier."}],"domainSpells":{}},"Home":{"grantedPowers":[{"name":"Guarded Hearth","type":"Su","level":8,"text":"At 8th level, you can create a ward that protects a specified area. Creating this ward takes 10 minutes of uninterrupted work. This ward has a maximum radius of 5 feet per 2 cleric levels you possess. When the ward is completed, you designate any number of creatures inside its area. Should any other creature enter the warded area, all of the selected creatures are immediately alerted (and awoken if they were asleep). The designated creatures also receive a sacred bonus equal to your Wisdom modifier on all saving throws and attack rolls while inside the warded area. This ward immediately ends if you leave the area. The ward lasts for 1 hour per cleric level. You can use this ability once per day."}],"domainSpells":{}}}},"Darkness":{"grantedPowers":[{"name":"Touch of Darkness","type":"Sp","level":1,"text":"As a melee touch attack, you can cause a creature's vision to be fraught with shadows and darkness. The creature touched treats all other creatures as if they had concealment, suffering a 20% miss chance on all attack rolls. This effect lasts for a number of rounds equal to 1/2 your cleric level (minimum 1). You can use this ability a number of times per day equal to 3 + your Wisdom modifier."},{"name":"Eyes of Darkness","type":"Su","level":8,"text":"At 8th level, your vision is not impaired by lighting conditions, even in absolute darkness and magic darkness. You can use this ability for a number of rounds per day equal to 1/2 your cleric level. These rounds do not need to be consecutive."}],"domainSpells":{"1":"Obscuring Mist","2":"Blindness/Deafness (only to cause blindness)","3":"Deeper Darkness","4":"Shadow Conjuration","5":"Summon Monster V (summons 1d3 shadows)","6":"Shadow Walk","7":"Power Word Blind","8":"Greater Shadow Evocation","9":"Shades"},"subdomainNames":["Loss","Moon","Night","Shadow"],"subdomains":{"Loss":{"grantedPowers":[{"name":"Aura of Forgetfulness","type":"Su","level":8,"text":"At 8th level, you can emit a 30-foot aura of forgetfulness for a number of rounds per day equal to your cleric level. Creatures you target in this area must make a Will save or have no memory of any time spent inside the area. In addition, spellcasters in the area lose one prepared spell or available spell slot per round spent in the area, starting with 1st-level spells and going up through higher-level spells. Spellcasters are allowed a save each round to negate this loss (this save is separate from the memory loss save). These rounds do not need to be consecutive."}],"domainSpells":{}},"Moon":{"grantedPowers":[{"name":"Moonfire","type":"Su","level":8,"text":"At 8th level, as a standard action, you can shoot a blast of divine moonlight from your eyes as a ranged touch attack against a single target within 30 feet. Moonfire deals 1d8 points of damage per 2 class levels you have, and the target is dazzled for 1 round per class level you have. Moonfire deals 1d10 points of damage per class level you have against lycanthropes. You can use this ability once per day at 8th level, and one additional time per day for every 4 levels beyond 8th."}],"domainSpells":{}},"Night":{"grantedPowers":[{"name":"Night Hunter","type":"Su","level":1,"text":"As a standard action, you can blend into the shadows of the night, becoming nearly invisible. As long as you are in an area of dim light or darkness, you are invisible (as per invisibility) to creatures without darkvision. This ability lasts for a number of rounds equal to 1/2 your cleric level (minimum 1). You can use this ability for a number of times per day equal to 3 + your Wisdom modifier."}],"domainSpells":{}},"Shadow":{"grantedPowers":[{"name":"Whispering Shadows","type":"Su","level":1,"text":"You can darken the shadows around you and cause them to hiss, confounding and distracting your enemies. As an immediate action, you can force a target within 30 feet to reroll a miss chance due to concealment or a saving throw against an illusion or necromancy spell. The target of this ability must keep the result of the second roll, even if it is worse than the original roll. You can use this ability a number of times per day equal to 3 + your Wisdom modifier."}],"domainSpells":{}}}},"Death":{"grantedPowers":[{"name":"Bleeding Touch","type":"Sp","level":1,"text":"As a melee touch attack, you can cause a living creature to take 1d6 points of damage per round. This effect persists for a number of rounds equal to 1/2 your cleric level (minimum 1) or until stopped with a DC 15 Heal check or any spell or effect that heals damage. You can use this ability a number of times per day equal to 3 + your Wisdom modifier."},{"name":"Death's Embrace","type":"Ex","level":8,"text":"At 8th level, you heal damage instead of taking damage from channeled negative energy. If the channeled negative energy targets undead, you heal hit points just like undead in the area."}],"domainSpells":{"1":"Cause Fear","2":"Death Knell","3":"Animate Dead","4":"Death Ward","5":"Slay Living","6":"Create Undead","7":"Destruction","8":"Create Greater Undead","9":"Wail of the Banshee"},"subdomainNames":["Murder","Plague","Psychopomp","Shadow","Undead"],"subdomains":{"Murder":{"grantedPowers":[{"name":"Killing Blow","type":"Su","level":8,"text":"At 8th level, weapons you use become infused with the power of death. Whenever you confirm a critical hit with a melee or ranged weapon, your attack deals an additional amount of bleed damage equal to half your cleric level. You can use this ability once per day at 8th level, plus one additional time per day for every four levels beyond 8th."}],"domainSpells":{}},"Plague":{"grantedPowers":[{"name":"Touch of Virulence","type":"Su","level":8,"text":"As a standard action, you can touch a diseased creature and exacerbate its condition. If it fails a Fortitude save (DC = 10 + 1/2 your cleric level + your Wisdom modifier), the creature takes damage as though it had failed its Fortitude save against the disease and any remaining onset time for the disease ends. You can use this ability once per day at 8th level, plus one additional time per day at 14th level and 20th level."}],"domainSpells":{}},"Psychopomp":{"grantedPowers":[{"name":"Spirit Touch","type":"Su","level":6,"text":"At 6th level, as a swift action, you can give your natural weapons or any weapons you wield the ghost touch weapon special ability. You can use this power a number of rounds per day equal to your cleric level. These rounds need not be consecutive."}],"domainSpells":{}},"Shadow":{"grantedPowers":[{"name":"Whispering Shadows","type":"Su","level":1,"text":"You can darken the shadows around you and cause them to hiss, confounding and distracting your enemies. As an immediate action, you can force a target within 30 feet to reroll a miss chance due to concealment or a saving throw against an illusion or necromancy spell. The target of this ability must keep the result of the second roll, even if it is worse than the original roll. You can use this ability a number of times per day equal to 3 + your Wisdom modifier."}],"domainSpells":{}},"Undead":{"grantedPowers":[{"name":"Death's Kiss","type":"Su","level":1,"text":"You can cause a creature to take on some of the traits of the undead with a melee touch attack. Touched creatures are treated as undead for the purposes of effects that heal or cause damage based on positive and negative energy. This effect lasts for a number of rounds equal to 1/2 your cleric level (minimum 1). It does not apply to the Turn Undead or Command Undead feats. You can use this ability a number of times per day equal to 3 + your Wisdom modifier."}],"domainSpells":{}}}},"Destruction":{"grantedPowers":[{"name":"Destructive Smite","type":"Su","level":1,"text":"You gain the destructive smite power: the supernatural ability to make a single melee attack with a morale bonus on damage rolls equal to 1/2 your cleric level (minimum 1). You must declare the destructive smite before making the attack. You can use this ability a number of times per day equal to 3 + your Wisdom modifier."},{"name":"Destructive Aura","type":"Su","level":8,"text":"At 8th level, you can emit a 30-foot aura of destruction for a number of rounds per day equal to your cleric level. All attacks made against targets in this aura (including you) gain a morale bonus on damage equal to 1/2 your cleric level and all critical threats are automatically confirmed. These rounds do not need to be consecutive."}],"domainSpells":{"1":"True Strike","2":"Shatter","3":"Rage","4":"Inflict Critical Wounds","5":"Shout","6":"Harm","7":"Disintegrate","8":"Earthquake","9":"Implosion"},"subdomainNames":["Catastrophe","Hatred","Rage","Torture"],"subdomains":{"Catastrophe":{"grantedPowers":[{"name":"Deadly Weather","type":"Su","level":8,"text":"At 8th level, you can unleash a furious call to the heavens, summoning forth an ever-changing storm of destruction for a number of rounds per day equal to your cleric level. This storm has a radius of 5 feet per cleric level. Each round, the storm has one of the following effects: driving rain (–4 on all Perception checks and ranged attack rolls), howling winds (–8 on Fly skill checks and ranged attack rolls), heavy snow (all terrain is considered difficult), or lightning bolt (as call lightning). Other effects depending on the weather might also apply (at the GM's discretion). You choose which effect takes place each round, but no effect may be repeated on the following round. These rounds do not need to be consecutive."}],"domainSpells":{}},"Hatred":{"grantedPowers":[{"name":"Hateful Aura","type":"Su","level":8,"text":"At 8th level, you can emit a 30-foot aura of hatred for a number of rounds per day equal to your cleric level. These rounds need not be consecutive. Enemies within this aura must attempt a Will save (DC = 10 + 1/2 your cleric level + your Wisdom modifier). Characters who fail their save are filled with hatred, and cannot consider other characters allies for the purpose of any actions or use any teamwork feats. The effect ends immediately if the creature leaves the aura, you end the aura as a free action, or you expend all rounds of this ability."}],"domainSpells":{}},"Rage":{"grantedPowers":[{"name":"Rage","type":"Su","level":8,"text":"At 8th level, you can enter a fearsome rage, like a barbarian, for a number of rounds per day equal to your cleric level. At 12th and 16th level, you can select one rage power. You cannot select any rage power that possesses a level requirement, but otherwise your barbarian level is equal to 1/2 your cleric level. These rounds of rage stack with any rounds of rage you might have from levels of barbarian."}],"domainSpells":{}},"Torture":{"grantedPowers":[{"name":"Painful Smite","type":"Su","level":1,"text":"Prior to making a melee attack roll, you can choose to convert all damage from that strike into nonlethal damage, adding your Wisdom modifier to the damage. If your attack hits, as a free action you can attempt an Intimidate check to demoralize the target. You gain a bonus on this Intimidate check equal to the amount of nonlethal damage dealt by the painful smite. You can use this ability a number of times per day equal to 3 + your Wisdom modifier."}],"domainSpells":{}}}},"Earth":{"grantedPowers":[{"name":"Acid Dart","type":"Sp","level":1,"text":"As a standard action, you can unleash an acid dart targeting any foe within 30 feet as a ranged touch attack. This acid dart deals 1d6 points of acid damage + 1 point for every two cleric levels you possess. You can use this ability a number of times per day equal to 3 + your Wisdom modifier."},{"name":"Acid Resistance","type":"Ex","level":6,"text":"At 6th level, you gain resist acid 10. This resistance increases to 20 at 12th level. At 20th level, you gain immunity to acid."}],"domainSpells":{"1":"Magic Stone","2":"Soften Earth and Stone","3":"Stone Shape","4":"Spike Stones","5":"Wall of Stone","6":"Stoneskin","7":"Elemental Body IV (earth only)","8":"Earthquake","9":"Elemental Swarm (earth spell only)"},"subdomainNames":["Caves","Metal","Petrification","Radiation"],"subdomains":{"Caves":{"grantedPowers":[{"name":"Tunnel Runner","type":"Su","level":8,"text":"At 8th level, you can move through tunnels and caves with ease. Activating this ability is a standard action. You can move across any stone surface as if under the effects of spider climb. You can also see very well in darkness, gaining darkvision out to a range of 60 feet. If you already possess darkvision, extend the range by 60 feet. While underground, you also gain an insight bonus equal to your cleric level on Stealth skill checks and an insight bonus equal to your Wisdom modifier on initiative checks. You can use this ability for 1 minute per day per cleric level you possess. These minutes do not need to be consecutive, but they must be spent in 1-minute increments."}],"domainSpells":{}},"Metal":{"grantedPowers":[{"name":"Metal Fist","type":"Su","level":1,"text":"As a swift action, you can turn your fists into metal for 1 round, allowing you to make unarmed strikes that deal 1d6 points of bludgeoning damage plus your Strength modifier. These unarmed strikes do not provoke attacks of opportunity, but attacking with both uses the two-weapon fighting rules as normal. In addition, these unarmed strikes ignore the hardness of items with a hardness of 10 or less. You can use this ability a number of times per day equal to 3 + your Wisdom modifier."}],"domainSpells":{}},"Petrification":{"grantedPowers":[{"name":"Fossil Form","type":"Su","level":1,"text":"At the beginning of your turn as a swift action, you can infuse your flesh with minerals, granting you cumbersome security. Until the beginning of your next turn, you are staggered, gain hardness 2, and gain a +2 bonus on saving throws against petrification. This hardness increases by 2 and your saving throw bonus increases by 1 for every 4 cleric levels you have. You can use this ability a number of times per day equal to 3 + your Wisdom modifier."}],"domainSpells":{}},"Radiation":{"grantedPowers":[{"name":"Radiating Touch","type":"Su","level":1,"text":"As a standard action that provokes attacks of opportunity, you can irradiate any unattended object for a number of rounds equal to your cleric level. While an object is irradiated, it emits a faint aura of transmutation. Any creature that passes within 5 feet of the aura must succeed at a Will save (DC equal to 10 + 1/2 your cleric level + your Wisdom modifier) or become sickened. You're immune to this object's effect. You can use this ability a number of times per day equal to 3 + your Wisdom modifier."}],"domainSpells":{}}}},"Erosion":{"grantedPowers":[{"name":"Rusting Touch","type":"Su","level":1,"text":"You can cause an opponent's metal armor or weapon to become dry and brittle as it magically corrodes and rusts. You make a melee touch attack against a creature wearing metal armor or wielding a metal weapon. If you hit, choose a metal weapon, suit of metal armor, or metal shield carried or worn by that creature. The object takes an amount of hit point damage equal to 1d6 + half your druid level. If the item is not magical, or if your caster level is greater than the item's caster level, this damage bypasses the item's hardness. You can use this ability a number of times per day equal to 3 + your Wisdom modifier."},{"name":"Erosion Aura","type":"Su","level":8,"text":"At 8th level, you can project an aura of magically enhanced erosion as a standard action. Objects made primarily of metal or stone within this aura lose 10 points of hardness. Magic items retain a minimum hardness equal to twice their enhancement bonus and can attempt a Fortitude saving throw (DC = 10 + half your druid level + your Wisdom modifier) to negate this effect. A construct made primarily of metal or stone must succeed at a Fortitude save or lose all damage reduction and hardness for 1 round. You can use this ability a number of times per day equal to 3 + your Wisdom modifier."}],"domainSpells":{"1":"Expeditious Excavation","2":"Soften Earth and Stone","3":"Disable Construct","4":"Rusting Grasp","5":"Transmute Rock to Mud","6":"Sympathetic Vibration","7":"Disintegrate","8":"Earthquake","9":"Implosion"},"subdomainNames":[],"subdomains":{}},"Evil":{"grantedPowers":[{"name":"Touch of Evil","type":"Sp","level":1,"text":"You can cause a creature to become sickened as a melee touch attack. Creatures sickened by your touch count as good for the purposes of spells with the evil descriptor. This ability lasts for a number of rounds equal to 1/2 your cleric level (minimum 1). You can use this ability a number of times per day equal to 3 + your Wisdom modifier."},{"name":"Scythe of Evil","type":"Su","level":8,"text":"At 8th level, you can give a weapon touched the unholy special weapon quality for a number of rounds equal to 1/2 your cleric level. You can use this ability once per day at 8th level, and an additional time per day for every four levels beyond 8th."}],"domainSpells":{"1":"Protection from Good","2":"Align Weapon (evil only)","3":"Magic Circle against Good","4":"Unholy Blight","5":"Dispel Good","6":"Create Undead","7":"Blasphemy","8":"Unholy Aura","9":"Summon Monster IX (evil spell only)"},"subdomainNames":["Cannibalism","Corruption","Daemon","Demodand","Demon","Devil","Fear","Kyton","Plague","Sahkil"],"subdomains":{"Cannibalism":{"grantedPowers":[{"name":"Consume the Enemy","type":"Su","level":1,"text":"As a full-round action that is considered an evil act and provokes attacks of opportunity, you can bite a helpless living or freshly killed creature, dealing 1d3 points of damage. By consuming the creature's flesh, you gain a +1 profane bonus on saving throw DCs for all spells, spell-like abilities, and supernatural abilities you use against creatures of the same type (and subtype, if humanoid or outsider) as the cannibalized creature. This effect lasts for a number of minutes equal to 1/2 your cleric level or until you use this ability against a different creature. At 5th, 10th, 15th, and 20th level, this bonus increases by 1 (+5 maximum). You can use this ability a number of times per day equal to 3 + your Wisdom modifier."}],"domainSpells":{}},"Corruption":{"grantedPowers":[{"name":"Spark Malfeasance","type":"Su","level":8,"text":"At 8th level, you can awaken the sinful desires of a target within 30 feet with a ranged touch attack. The target suffers extreme guilt and is sickened for a number of rounds equal to 1/2 your cleric level. To end the effect earlier, the target can willingly commit an evil act (if it is of good alignment) or attempt a Will save (DC = 10 + 1/2 your cleric level + your Wisdom modifier) at the beginning of its turn each round. Creatures that succeed at their saving throws are immune to this ability for 24 hours. You can use this ability once per day at 8th level, and an additional time per day for every 4 levels beyond 8th."}],"domainSpells":{}},"Daemon":{"grantedPowers":[{"name":"Whispering Evil","type":"Su","level":8,"text":"At 8th level, as a standard action, you can whisper a hypnotizing litany of empty promises. Each enemy within a 30-foot emanation that can hear you must succeed on a Will saving throw or become fascinated for as long as you continue the litany. You can use this power a number of rounds per day equal to your cleric level, but these rounds do not need to be consecutive. This is a mind-affecting effect."}],"domainSpells":{}},"Demodand":{"grantedPowers":[{"name":"Faith-Stealing Strike","type":"Su","level":1,"text":"You can make a single melee attack using your highest base attack bonus against a creature capable of casting divine spells. If you damage the creature, it must succeed at a Will save (DC = 10 + 1/2 your cleric level + your Wisdom modifier) or be unable to cast any divine spells for 1 round. If you do not damage your target with the attack, this ability is expended with no effect. You can use this ability a number of times per day equal to 3 + your Wisdom modifier."}],"domainSpells":{}},"Demon":{"grantedPowers":[{"name":"Fury of the Abyss","type":"Su","level":1,"text":"As a swift action, you can give yourself an enhancement bonus equal to 1/2 your cleric level (minimum +1) on melee attacks, melee damage rolls, and combat maneuver checks. This bonus lasts for 1 round. During this round, you take a –2 penalty to AC. You can use this ability for a number of times per day equal to 3 + your Wisdom modifier."}],"domainSpells":{}},"Devil":{"grantedPowers":[{"name":"Hell's Corruption","type":"Su","level":1,"text":"You can cause a creature to become more susceptible to corruption as a melee touch attack. Creatures touched take a –2 penalty on all saving throws and must roll all opposed skill checks twice, taking the worse result. This effect lasts for a number of rounds equal to 1/2 your cleric level (minimum 1). You can use this ability for a number of times per day equal to 3 + your Wisdom modifier."}],"domainSpells":{}},"Fear":{"grantedPowers":[{"name":"Feed on Fear","type":"Su","level":8,"text":"At 8th level, as an immediate action upon successfully landing a melee attack on a creature that is already suffering from a fear effect, you deal 2d6 extra points of damage and gain an equal amount of temporary hit points. These temporary hit points last for 24 hours or until lost. You can use this ability once per day at 8th level, and an additional time per day for every 4 levels beyond 8th."}],"domainSpells":{}},"Kyton":{"grantedPowers":[{"name":"Pain Is Power","type":"Su","level":8,"text":"At 8th level, after taking damage from any source, you may attempt a DC 25 concentration check as an immediate action. If you succeed, you gain the benefits of a blessing of fervor spell for a number of rounds equal to 1/2 your cleric level. If you fail, this ability is expended with no effect. You can use this ability once at 8th level, plus an additional time for every 4 levels you are beyond 8th."}],"domainSpells":{}},"Plague":{"grantedPowers":[{"name":"Touch of Virulence","type":"Su","level":8,"text":"As a standard action, you can touch a diseased creature and exacerbate its condition. If it fails a Fortitude save (DC = 10 + 1/2 your cleric level + your Wisdom modifier), the creature takes damage as though it had failed its Fortitude save against the disease and any remaining onset time for the disease ends. You can use this ability once per day at 8th level, plus one additional time per day at 14th level and 20th level."}],"domainSpells":{}},"Sahkil":{"grantedPowers":[{"name":"Touch of Paranoia","type":"Su","level":1,"text":"You can imbue a target with great suspicion and doubt as a melee touch attack. A creature affected by your touch does not have allies and is not considered to be an ally to any other creature, including other creatures affected by this effect. The affected creature cannot move freely through its allies' spaces, flank creatures with them, cooperate with them using teamwork feats, or give or receive benefits from the aid another action or any spells or effect that affects only allies. This ability lasts for a number of rounds equal to 1/2 your cleric level (minimum 1). You can use this ability a number of times per day equal to 3 + your Wisdom modifier."}],"domainSpells":{}}}},"Fire":{"grantedPowers":[{"name":"Fire Bolt","type":"Sp","level":1,"text":"As a standard action, you can unleash a scorching bolt of divine fire from your outstretched hand. You can target any single foe within 30 feet as a ranged touch attack with this bolt of fire. If you hit the foe, the fire bolt deals 1d6 points of fire damage + 1 point for every two cleric levels you possess. You can use this ability a number of times per day equal to 3 + your Wisdom modifier."},{"name":"Fire Resistance","type":"Ex","level":6,"text":"At 6th level, you gain resist fire 10. This resistance increases to 20 at 12th level. At 20th level, you gain immunity to fire."}],"domainSpells":{"1":"Burning Hands","2":"Produce Flame","3":"Fireball","4":"Wall of Fire","5":"Fire Shield","6":"Fire Seeds","7":"Elemental Body IV (fire only)","8":"Incendiary Cloud","9":"Elemental Swarm (fire spell only)"},"subdomainNames":["Arson","Ash","Smoke"],"subdomains":{"Arson":{"grantedPowers":[{"name":"Call Fire","type":"Su","level":1,"text":"As a standard action, you can stretch out your hand toward any visible fire source within 60 feet and beckon it toward you. This causes a ribbon-thin streak of fire to approach you in a straight line through the air. Any creature directly in the fire ribbon's path takes 1d4 points of fire damage; a successful Reflex save (DC = 10 + half your class level + your Wisdom modifier) negates this damage. When the ribbon of fire reaches your hand, it either extinguishes or lights a flammable object of your choice that you're holding. You can use this ability a number of times per day equal to 3 + your Wisdom modifier."}],"domainSpells":{}},"Ash":{"grantedPowers":[{"name":"Wall of Ashes","type":"Su","level":8,"text":"At 8th level, you can create a wall of swirling ashes anywhere within 100 feet. This wall is up to 20 feet high and up to 10 feet long per cleric level you possess. The wall of ash blocks line of sight, and any creature passing through it must make a Fortitude save or be blinded for 1d4 rounds. The wall of ash reveals invisible creatures that are inside it or adjacent to it, although they become invisible again if they move away from the wall. You can use this ability for a number of minutes per day equal to your cleric level, but these minutes do not need to be consecutive."}],"domainSpells":{}},"Smoke":{"grantedPowers":[{"name":"Cloud of Smoke","type":"Su","level":1,"text":"As a standard action, you can create a 5-foot-radius cloud of smoke. This power has a range of 30 feet. Creatures inside the cloud take a –2 penalty on attack rolls and Perception skill checks for as long as they remain inside and for 1 round after exiting the cloud. Creatures inside the cloud gain concealment from attacks made by opponents that are not adjacent to them. You can use this ability a number of times per day equal to 3 + your Wisdom modifier."}],"domainSpells":{}}}},"Glory":{"grantedPowers":[{"name":"Touch of Glory","type":"Sp","level":1,"text":"You can cause your hand to shimmer with divine radiance, allowing you to touch a creature as a standard action and give it a bonus equal to your cleric level on a single Charisma-based skill check or Charisma ability check. This ability lasts for 1 hour or until the creature touched elects to apply the bonus to a roll. You can use this ability to grant the bonus a number of times per day equal to 3 + your Wisdom modifier."},{"name":"Divine Presence","type":"Su","level":8,"text":"At 8th level, you can emit a 30-foot aura of divine presence for a number of rounds per day equal to your cleric level. All allies within this aura are treated as if under the effects of a sanctuary spell with a DC equal to 10 + 1/2 your cleric level + your Wisdom modifier. These rounds do not need to be consecutive. Activating this ability is a standard action. If an ally leaves the area or makes an attack, the effect ends for that ally. If you make an attack, the effect ends for you and your allies."}],"domainSpells":{"1":"Shield of Faith","2":"Bless Weapon","3":"Searing Light","4":"Holy Smite","5":"Righteous Might","6":"Undeath to Death","7":"Holy Sword","8":"Holy Aura","9":"Gate"},"subdomainNames":["Chivalry","Heroism","Honor","Hubris","Legend"],"subdomains":{"Chivalry":{"grantedPowers":[{"name":"Bolstering Touch","type":"Sp","level":1,"text":"You can touch a willing creature as a standard action, bracing it against frightening situations and allowing it to remain calm. The first fear effect that would affect the subject within the next hour is suppressed for the first 1d4 rounds of its effect. If you touch a creature currently suffering from an ongoing fear effect, this ability instead suppresses the ongoing fear effect for 1 round. The rounds during which the subject ignores the triggering fear effect still count against the effect's duration. If the fear effect is suppressed for longer than it lasts, the subject isn't affected by the fear effect at all. You can use this ability a number of times per day equal to 3 + your Wisdom modifier."}],"domainSpells":{}},"Heroism":{"grantedPowers":[{"name":"Aura of Heroism","type":"Su","level":8,"text":"At 8th level, you can emit a 30-foot aura of heroism for a number of rounds per day equal to your cleric level. Using this ability is a swift action. Allies in the area are treated as if they were under the effects of heroism. These rounds do not need to be consecutive."}],"domainSpells":{}},"Honor":{"grantedPowers":[{"name":"Honor Bound","type":"Su","level":1,"text":"With a touch, you can remind a creature of its duties and responsibilities, granting it a new saving throw against each enchantment (charm) or enchantment (compulsion) effect that currently affects it. If the saving throw is successful, the enchantment effect is ended. This power only affects effects that allow a save. If you fail a save against such an effect, you can use this ability as an immediate action to grant yourself an additional save. Once the target (either you or a touched creature) has made one additional save per effect, this ability has no further effect on that particular enchantment effect. You can use this ability a number of times per day equal to 3 + your Wisdom modifier."}],"domainSpells":{}},"Hubris":{"grantedPowers":[{"name":"Divine Demand","type":"Su","level":6,"text":"At 6th level, you can petition your divine patron for far greater power than you deserve. Activating this ability is a swift action that you must use as you cast a spell that has a reduced (but not negated) effect on a successful save. The saving throw DC of the spell increases by 2, and you gain a +2 bonus on caster level checks to overcome spell resistance with the spell. Any creature that succeeds at the saving throw instead avoids the effect entirely. If half or more of the targets are unaffected, you become shaken for a number of rounds equal to the spell's level. If all of the targets are unaffected, you instead lose the ability to cast divine spells, channel energy, and use domain powers for 1d4+1 rounds; you can end this loss as a full-round action by loudly apologizing to your patron deity as a full-round action that provokes attacks of opportunity. You can use this ability once per day at 6th level, and one additional time per day for every 4 levels beyond 6th."}],"domainSpells":{}},"Legend":{"grantedPowers":[{"name":"Witness the Legend","type":"Su","level":8,"text":"At 8th level, as a move action, you can extol the virtues of yourself or an ally within 60 feet that you can see. This causes the target to shed light like a torch for 1 minute, and while the effect lasts, you can expend a daily use of your touch of glory domain ability as an immediate action to add 1d6 to an attack, saving throw, skill check, or ability check attempted by the target; for a roll to confirm a critical hit or save against a fear effect, you instead add 1d12. You can use this ability once per day at 8th level and one additional time per day for every 4 levels beyond 8th."}],"domainSpells":{}}}},"Good":{"grantedPowers":[{"name":"Touch of Good","type":"Sp","level":1,"text":"You can touch a creature as a standard action, granting a sacred bonus on attack rolls, skill checks, ability checks, and saving throws equal to half your cleric level (minimum 1) for 1 round. You can use this ability a number of times per day equal to 3 + your Wisdom modifier."},{"name":"Holy Lance","type":"Su","level":8,"text":"At 8th level, you can give a weapon you touch the holy special weapon quality for a number of rounds equal to 1/2 your cleric level. You can use this ability once per day at 8th level, and an additional time per day for every four levels beyond 8th."}],"domainSpells":{"1":"Protection From Evil","2":"Align Weapon (good only)","3":"Magic Circle Against Evil","4":"Holy Smite","5":"Dispel Evil","6":"Blade Barrier","7":"Holy Word","8":"Holy Aura","9":"Summon Monster IX (good spell only)"},"subdomainNames":["Agathion","Archon","Azata","Friendship","Redemption"],"subdomains":{"Agathion":{"grantedPowers":[{"name":"Protective Aura","type":"Su","level":8,"text":"At 8th level, you can emit a 30-foot protective aura as a standard action. Allies in this aura receive a +2 deflection bonus to AC and a +2 resistance bonus on all saving throws. In addition, allies in the area gain the benefits of protection from evil (although the AC bonus and saving throw bonus do not stack with those granted by this effect). You can use this ability for a number of rounds per day equal to your cleric level. These rounds do not have to be consecutive."}],"domainSpells":{}},"Archon":{"grantedPowers":[{"name":"Aura of Menace","type":"Su","level":8,"text":"At 8th level, you can emit a 30-foot aura of menace as a standard action. Enemies in this aura take a -2 penalty to AC and on attacks and saves as long as they remain inside the aura. You can use this ability for a number of rounds per day equal to your cleric level. These rounds do not need to be consecutive."}],"domainSpells":{}},"Azata":{"grantedPowers":[{"name":"Elysium's Call","type":"Su","level":1,"text":"With a touch, you can imbue creatures with the spirit of Elysium, lifting their spirits and freeing them from bonds. The creatures touched can immediately reroll any failed saving throws against spells and spell-like abilities of the enchantment (charm) and enchantment (compulsion) subschools. In addition, targets receive a +2 sacred bonus on such saving throws and a +2 sacred bonus on CMB checks to escape a grapple. Finally, targets can ignore up to 5 feet of difficult terrain each round, as if they had the Nimble Moves feat. These bonuses last for a number of rounds equal to 1/2 your cleric level (minimum 1), although the saving throw reroll only applies when the creature is touched. You can use this ability for a number of rounds per day equal to 3 + your Wisdom modifier."}],"domainSpells":{}},"Friendship":{"grantedPowers":[{"name":"Powerful Bond","type":"Su","level":1,"text":"As a free action, you can open a link to communicate telepathically with a single ally within 60 feet. The telepathic link is two-way and lasts for 1 minute. Unlike normal telepathy, this ability requires a shared language. You can use this ability a number of times per day equal to 3 + your Wisdom modifier."}],"domainSpells":{}},"Redemption":{"grantedPowers":[{"name":"Aura of Sanctification","type":"Su","level":8,"text":"At 8th level, as an immediate action, you can emit a 30-foot-radius aura of sanctification for a number of rounds per day equal to your cleric level. These rounds do not need to be consecutive. Within this aura, effects that are specifically harmful to good-aligned creatures are inverted so that they no longer harm good creatures and instead harm evil creatures. Similarly, effects that are specifically beneficial to evil creatures instead become beneficial only to good creatures."}],"domainSpells":{}}}},"Healing":{"grantedPowers":[{"name":"Rebuke Death","type":"Sp","level":1,"text":"You can touch a living creature as a standard action, healing it for 1d4 points of damage plus 1 for every two cleric levels you possess. You can only use this ability on a creature that is below 0 hit points. You can use this ability a number of times per day equal to 3 + your Wisdom modifier."},{"name":"Healer's Blessing","type":"Su","level":6,"text":"At 6th level, all of your cure spells are treated as if they were empowered, increasing the amount of damage healed by half (+50%). This does not apply to damage dealt to undead with a cure spell. This does not stack with the Empower Spell metamagic feat."}],"domainSpells":{"1":"Cure Light Wounds","2":"Cure Moderate Wounds","3":"Cure Serious Wounds","4":"Cure Critical Wounds","5":"Breath Of Life","6":"Heal","7":"Regenerate","8":"Mass Cure Critical Wounds","9":"Mass Heal"},"subdomainNames":["Medicine","Restoration","Resurrection"],"subdomains":{"Medicine":{"grantedPowers":[{"name":"Blessed Surgery","type":"Su","level":1,"text":"Your divine patron guides your healing hands, allowing you to perform minor miracles with mundane cures. You can use this ability as a free action when using the Heal skill in order to roll the check twice and take the higher result. When you're using this ability, any use of the Heal skill requiring 1 hour instead takes at most 1 minute. You can use this ability a number of times per day equal to 3 + your Wisdom modifier."}],"domainSpells":{}},"Restoration":{"grantedPowers":[{"name":"Restorative Touch","type":"Su","level":1,"text":"You can touch a creature, letting the healing power of your deity flow through you to relieve the creature of a minor condition. Your touch can remove the dazed, fatigued, shaken, sickened, or staggered condition. You choose which condition is removed. You can use this ability a number of times per day equal to 3 + your Wisdom modifier."}],"domainSpells":{}},"Resurrection":{"grantedPowers":[{"name":"Gift of Life","type":"Su","level":8,"text":"At 8th level, you can touch a creature that has died within the past minute to grant it a few moments of life. The dead creature returns to life for a number of rounds equal to your cleric level. Creatures returned to life in this way have a number of hit points equal to half your cleric level, and continue to be affected by any still-active spells, conditions, or afflictions present at the time of their death. At the end of this time, the creature dies again. The creature is free to act as it sees fit during this time. You are granted no control over it. You can use this power once per day at 8th level, plus one additional time per day for every four levels beyond 8th."}],"domainSpells":{}}}},"Knowledge":{"grantedPowers":[{"name":"Lore Keeper","type":"Sp","level":1,"text":"You can touch a creature to learn about its abilities and weaknesses. With a successful touch attack, you gain information as if you made the appropriate Knowledge skill check with a result equal to 15 + your cleric level + your Wisdom modifier."},{"name":"Remote Viewing","type":"Sp","level":6,"text":"Starting at 6th level, you can use clairvoyance/clairaudience at will as a spell-like ability using your cleric level as the caster level. You can use this ability for a number of rounds per day equal to your cleric level. These rounds do not need to be consecutive."}],"domainSpells":{"1":"Comprehend Languages","2":"Detect Thoughts","3":"Speak With Dead","4":"Divination","5":"True Seeing","6":"Find The Path","7":"Legend Lore","8":"Discern Location","9":"Foresight"},"subdomainNames":["Aeon","Education","Espionage","Memory","Thought"],"subdomains":{"Aeon":{"grantedPowers":[{"name":"Void Form","type":"Su","level":6,"text":"At 6th level, you can become semi-tangible as a standard action. While in this form, you are immune to critical hits and gain a +1 deflection bonus to AC. This bonus increases by 1 at 8th level and every 4 levels thereafter. You can use this power a number of rounds per day equal to your cleric level. These rounds need not be consecutive."}],"domainSpells":{}},"Education":{"grantedPowers":[{"name":"Teaching Moment","type":"Su","level":8,"text":"At 8th level, when you or an ally within 30 feet rolls a natural 1 or a natural 20 on an attack roll, an ability check, a skill check, or a saving throw, as an immediate action you can grant all allies within 30 feet special insights that help them overcome similar challenges. Once during the next minute, each affected creature can choose to roll twice and take the better result before attempting an attack roll, ability check, skill check, or saving throw. You can use this ability once per day at 8th level, and one additional time per day for every 4 cleric levels beyond 8th."}],"domainSpells":{}},"Espionage":{"grantedPowers":[{"name":"Deep Cover","type":"Su","level":1,"text":"When you prepare your spells, you can also choose one cover identity-whether that of a real person or a fictitious one. You can assume the disguise of your cover identity in half the normal amount of time. When targeted by a spell or effect that would compromise your chosen disguise (such as detect evil, detect thoughts, or zone of truth), as an immediate action you can force the creature using the ability to attempt a Will save (DC = 10 + 1/2 your cleric level + your Wisdom modifier). If the creature fails, it gains false information in keeping with your cover identity. You can use this false information ability a number of times per day equal to 3 + your Wisdom modifier."}],"domainSpells":{}},"Memory":{"grantedPowers":[{"name":"Recall","type":"Su","level":1,"text":"With a touch, you can cause a creature to recall some bit of forgotten lore or information. The creature can retry any Knowledge skill check it has made within the past minute, gaining a insight bonus on the check equal to your Wisdom modifier. You can use this ability a number times per day equal to 3 + your Wisdom modifier."}],"domainSpells":{}},"Thought":{"grantedPowers":[{"name":"Read Minds","type":"Su","level":8,"text":"At 8th level, you can broaden your mental spectrum to encompass those around you. Doing so allows you to read the mind of every creature within 30 feet as if you had cast detect thoughts. This ability allows you to read the surface thoughts of any creature that you are aware of after only 1 round of concentration. Creatures in this area are allowed a Will save to negate the effect. The DC of this Will save is 10 + 1/2 your cleric level + your Wisdom modifier. You can use this ability for a number of rounds per day equal to your cleric level. These rounds do not need to be consecutive."}],"domainSpells":{}}}},"Law":{"grantedPowers":[{"name":"Touch of Law","type":"Sp","level":1,"text":"You can touch a willing creature as a standard action, infusing it with the power of divine order and allowing it to treat all attack rolls, skill checks, ability checks, and saving throws for 1 round as if the natural d20 roll resulted in an 11. You can use this ability a number of times per day equal to 3 + your Wisdom modifier."},{"name":"Staff of Order","type":"Su","level":8,"text":"At 8th level, you can give a weapon touched the axiomatic special weapon quality for a number of rounds equal to 1/2 your cleric level. You can use this ability once per day at 8th level, and an additional time per day for every four levels beyond 8th."}],"domainSpells":{"1":"Protection From Chaos","2":"Align Weapon (law only)","3":"Magic Circle Against Chaos","4":"Order's Wrath","5":"Dispel Chaos","6":"Hold Monster","7":"Dictum","8":"Shield Of Law","9":"Summon Monster IX (law spell only)"},"subdomainNames":["Archon","Devil","Inevitable","Judgment","Kyton","Legislation","Loyalty","Slavery","Sovereignty","Tyranny"],"subdomains":{"Archon":{"grantedPowers":[{"name":"Aura of Menace","type":"Su","level":8,"text":"At 8th level, you can emit a 30-foot aura of menace as a standard action. Enemies in this aura take a -2 penalty to AC and on attacks and saves as long as they remain inside the aura. You can use this ability for a number of rounds per day equal to your cleric level. These rounds do not need to be consecutive."}],"domainSpells":{}},"Devil":{"grantedPowers":[{"name":"Hell's Corruption","type":"Su","level":1,"text":"You can cause a creature to become more susceptible to corruption as a melee touch attack. Creatures touched take a -2 penalty on all saving throws and must roll all opposed skill checks twice, taking the worse result. This effect lasts for a number of rounds equal to 1/2 your cleric level (minimum 1). You can use this ability for a number of times per day equal to 3 + your Wisdom modifier."}],"domainSpells":{}},"Inevitable":{"grantedPowers":[{"name":"Command","type":"Su","level":1,"text":"As a standard action, you can give a creature an emotionless yet undeniable order, as per the spell command. A Will save negates this effect. You cannot target a creature more than once per day with this ability. You can use this ability a number of times per day equal to 3 + your Wisdom modifier."}],"domainSpells":{}},"Judgment":{"grantedPowers":[{"name":"Chastisement","type":"Su","level":1,"text":"As a standard action, you can cast a strengthened spell against a creature that damaged you since your last turn. This spell must target the creature that damaged you, and is cast at +1 caster level. Area of effect spells cannot be used in conjunction with this ability, but other spells that target multiple creatures may be. You can use this ability a number of times per day equal to 3 + your Wisdom modifier."}],"domainSpells":{}},"Kyton":{"grantedPowers":[{"name":"Pain Is Power","type":"Su","level":8,"text":"At 8th level, after taking damage from any source, you may attempt a DC 25 concentration check as an immediate action. If you succeed, you gain the benefits of a blessing of fervor spell for a number of rounds equal to 1/2 your cleric level. If you fail, this ability is expended with no effect. You can use this ability once at 8th level, plus an additional time for every 4 levels you are beyond 8th."}],"domainSpells":{}},"Legislation":{"grantedPowers":[{"name":"Prohibition","type":"Su","level":1,"text":"As a standard action, you can command a creature within 30 feet to refrain from committing a particular action (including any referenced in the spell forbid action). If the creature performs the named action before the beginning of your next turn, it takes 1d6 points of damage + 1 point for every 2 cleric levels you possess and the effect ends. This is a language-dependent effect. You can use this ability a number of times per day equal to 3 + your Wisdom modifier. If you have the spell rune domain power, you can attach a spell effect to the prohibition as if it were the spell rune domain ability; the spell takes effect if the creature performs the named action. This spell must be of at least 1 level lower than the highest-level cleric spell you can cast, and it must target one or more creatures. Regardless of the number of targets the spell can normally affect, it affects only the creature that triggers the rune. Attaching a spell in this way extends the duration of the prohibition by a number of rounds equal to the spell's level, or until it is discharged."}],"domainSpells":{}},"Loyalty":{"grantedPowers":[{"name":"Touch of Loyalty","type":"Su","level":1,"text":"As a standard action, you can touch a willing creature, granting it a +4 sacred bonus on saving throws to resist charm, compulsion, and fear effects for 1 hour. You can use this ability a number of times per day equal to 3 + your Wisdom modifier."}],"domainSpells":{}},"Slavery":{"grantedPowers":[{"name":"Master's Yoke","type":"Su","level":8,"text":"At 8th level, you can attempt to assert your dominance over any visible creature within 30 feet by declaring the target your property. The target can resist this effect with a successful Will save (DC = 10 + half your class level + your Wisdom modifier). If the target fails the save, it is affected as if by dominate monster for a number of rounds equal to half your class level. The target can choose to ignore any order you give and instead take 2 points of Constitution damage and become staggered for 1 round. You can use this ability once per day at 8th level, and an additional time per day for every 4 levels beyond 8th. This is a language-based mind-affecting effect."}],"domainSpells":{}},"Sovereignty":{"grantedPowers":[{"name":"Demand Subjugation","type":"Sp","level":8,"text":"At 8th level, you can force a defeated creature to accept a binding pact as a condition of its surrender, as if you are using lesser geas, except the creature must have a number of Hit Dice equal to or less than your cleric level. At 16th level, this ability functions as per geas/quest. You can use this ability a number of times per day equal to 3 + your Wisdom modifier."}],"domainSpells":{}},"Tyranny":{"grantedPowers":[{"name":"Tyrannical Strike","type":"Su","level":8,"text":"At 8th level, as an immediate action upon successfully landing a melee attack on an opponent, you can choose to forgo the damage (but not any other effects of the attack) to instead affect the creature you hit as per a greater command spell, with a caster level equal to your class level. You can use this ability once per day at 8th level, and an additional time per day for every 4 levels beyond 8th."}],"domainSpells":{}}}},"Liberation":{"grantedPowers":[{"name":"Liberation","type":"Su","level":1,"text":"You have the ability to ignore impediments to your mobility. For a number of rounds per day equal to your cleric level, you can move normally regardless of magical effects that impede movement, as if you were affected by freedom of movement. This effect occurs automatically as soon as it applies. These rounds do not need to be consecutive."},{"name":"Freedom's Call","type":"Su","level":8,"text":"At 8th level, you can emit a 30-foot aura of freedom for a number of rounds per day equal to your cleric level. Allies within this aura are not affected by the confused, grappled, frightened, panicked, paralyzed, pinned, or shaken conditions. This aura only suppresses these effects, and they return once a creature leaves the aura or when the aura ends, if applicable. These rounds do not need to be consecutive."}],"domainSpells":{"1":"Remove Fear","2":"Remove Paralysis","3":"Remove Curse","4":"Freedom Of Movement","5":"Break Enchantment","6":"Greater Dispel Magic","7":"Refuge","8":"Mind Blank","9":"Freedom"},"subdomainNames":["Freedom","Revolution","Self-Realization"],"subdomains":{"Freedom":{"grantedPowers":[{"name":"Liberty's Blessing","type":"Sp","level":1,"text":"You touch a willing creature as a standard action, granting it a boon. A creature with this boon can, as a swift action, make a saving throw against a single spell or effect it is suffering from that grants a save. The DC of the saving throw is equal to the original DC of the spell or effect. If the saving throw is successful, the effect ends. This boon lasts for 1 minute or until successfully used to remove a spell or effect, whichever duration is shorter. You can use this ability for a number of times equal to 3 + your Wisdom modifier."}],"domainSpells":{}},"Revolution":{"grantedPowers":[{"name":"Powerful Persuader","type":"Su","level":8,"text":"At 8th level, when you make a Diplomacy or Intimidate check, you can roll twice and take the higher result. Using this ability is a free action. You can use this ability once per day at 8th level, plus one additional time per day for every 2 levels beyond 8th."}],"domainSpells":{}},"Self-Realization":{"grantedPowers":[{"name":"Perfected Form","type":"Su","level":1,"text":"You maintain an unshakable sense of who you are, and no force can compel you to be anything else. You gain a +1 sacred (if your patron is good or neutral) or profane (if your patron is evil) bonus on saving throws against polymorph, petrification, and transmutation effects. This bonus increases by 1 for every 5 cleric levels you have (maximum +5). Once per day when you succeed at a saving throw against such an effect, you can gain a surge of self-confidence as an immediate action that grants you a number of temporary hit points equal to your cleric level and a +2 morale bonus on attack rolls, skill checks, and saving throws; both effects last for 1 minute."}],"domainSpells":{}}}},"Luck":{"grantedPowers":[{"name":"Bit of Luck","type":"Sp","level":1,"text":"You can touch a willing creature as a standard action, giving it a bit of luck. For the next round, any time the target rolls a d20, he may roll twice and take the more favorable result. You can use this ability a number of times per day equal to 3 + your Wisdom modifier."},{"name":"Good Fortune","type":"Ex","level":6,"text":"At 6th level, as an immediate action, you can reroll any one d20 roll you have just made before the results of the roll are revealed. You must take the result of the reroll, even if it's worse than the original roll. You can use this ability once per day at 6th level, and one additional time per day for every six cleric levels beyond 6th."}],"domainSpells":{"1":"True Strike","2":"Aid","3":"Protection From Energy","4":"Freedom of Movement","5":"Break Enchantment","6":"Mislead","7":"Spell Turning","8":"Moment of Prescience","9":"Miracle"},"subdomainNames":["Curse","Fate","Imagination"],"subdomains":{"Curse":{"grantedPowers":[{"name":"Malign Eye","type":"Su","level":1,"text":"As a standard action, you can afflict one target within 30 feet with your malign eye, causing it to take a –2 penalty on all saving throws against your spells. The effect lasts for 1 minute or until the target hits you with an attack. You can use this ability for a number of times per day equal to 3 + your Wisdom modifier."}],"domainSpells":{}},"Fate":{"grantedPowers":[{"name":"Tugging Strands","type":"Su","level":8,"text":"At 8th level, you can force a creature within line of sight to reroll any one roll that it has just made before the result of the roll is revealed. The result of the reroll must be taken, even if it is worse than the original roll. You can use this ability once per day at 8th level, and one additional time per day for every 6 levels beyond 8th."}],"domainSpells":{}},"Imagination":{"grantedPowers":[{"name":"Haze of Daydreams","type":"Su","level":6,"text":"At 6th level, you can emit a 15-foot-radius haze of daydreams for a number of rounds per day equal to your cleric level. These rounds do not need to be consecutive. Creatures within the haze gain the fascinated condition unless they succeed at a Will save (DC equal to 10 + 1/2 your cleric level + your Wisdom modifier). You may designate a number of creatures equal to your cleric level that are not affected by the haze. The fascinated condition ends immediately when the creatures leave the area or the aura expires."}],"domainSpells":{}}}},"Madness":{"grantedPowers":[{"name":"Vision of Madness","type":"Sp","level":1,"text":"You can give a creature a vision of madness as a melee touch attack. Choose one of the following: attack rolls, saving throws, or skill checks. The target receives a bonus to the chosen rolls equal to 1/2 your cleric level (minimum +1) and a penalty to the other two types of rolls equal to 1/2 your cleric level (minimum –1). This effect fades after 3 rounds. You can use this ability a number of times per day equal to 3 + your Wisdom modifier."},{"name":"Aura of Madness","type":"Su","level":8,"text":"At 8th level, you can emit a 30-foot aura of madness for a number of rounds per day equal to your cleric level. Enemies within this aura are affected by confusion unless they make a Will save with a DC equal to 10 + 1/2 your cleric level + your Wisdom modifier. The confusion effect ends immediately when the creature leaves the area or the aura expires. Creatures that succeed on their saving throw are immune to this aura for 24 hours. These rounds do not need to be consecutive."}],"domainSpells":{"1":"Lesser Confusion","2":"Touch of Idiocy","3":"Rage","4":"Confusion","5":"Nightmare","6":"Phantasmal Killer","7":"Insanity","8":"Scintillating Pattern","9":"Weird"},"subdomainNames":["Insanity","Nightmare","Truth"],"subdomains":{"Insanity":{"grantedPowers":[{"name":"Insane Focus","type":"Su","level":1,"text":"You can touch a willing creature as a standard action, granting it a +4 bonus on all saving throws made against mind-affecting effects and immunity to confusion. This bonus lasts for 1 minute. If the creature fails a saving throw against a mind-affecting effect during this period, it loses its immunity to confusion and is immediately confused for one round. You can use this ability a number of times per day equal to 3 + your Wisdom modifier."}],"domainSpells":{}},"Nightmare":{"grantedPowers":[{"name":"Fearful Touch","type":"Su","level":1,"text":"As a standard action, you can make a melee touch attack against a creature, causing it to experience terrible hallucinations for 1 round. During this time, the creature loses any immunity to fear effects it might possess and takes a –2 penalty on attack rolls made against you. In addition, the creature takes a penalty on Will saves made against fear effects equal to 1/2 your cleric level (minimum –1). This power is a mind-affecting effect. You can use this ability for a number of times per day equal to 3 + your Wisdom modifier."}],"domainSpells":{}},"Truth":{"grantedPowers":[{"name":"Dawning Realization","type":"Su","level":8,"text":"At 8th level, you can impart a shared vision of unfathomable ineffability to a living creature you touch as a standard action, after which your turn immediately ends. You are dazed and the target confused for 1 round by what you both learn. On the following round, you are both staggered for 1 round by the ramifications of your discovery. On the third round, you are confused and the target dazed for 1 round as you attempt to regain your bearings. Each round, the target can attempt a Will save with a DC equal to 10 + 1/2 your cleric level + your Wisdom modifier to negate that round's effects for both of you, though the effect does not end until the end of the third round. This is a mind-affecting effect that you can use a number of times per day equal to 1/2 your class level."}],"domainSpells":{}}}},"Magic":{"grantedPowers":[{"name":"Hand of the Acolyte","type":"Su","level":1,"text":"You can cause your melee weapon to fly from your grasp and strike a foe before instantly returning. As a standard action, you can make a single attack using a melee weapon at a range of 30 feet. This attack is treated as a ranged attack with a thrown weapon, except that you add your Wisdom modifier to the attack roll instead of your Dexterity modifier (damage still relies on Strength). This ability cannot be used to perform a combat maneuver. You can use this ability a number of times per day equal to 3 + your Wisdom modifier."},{"name":"Dispelling Touch","type":"Sp","level":8,"text":"At 8th level, you can use a targeted dispel magic effect as a melee touch attack. You can use this ability once per day at 8th level and one additional time per day for every four cleric levels beyond 8th."}],"domainSpells":{"1":"Identify","2":"Magic Mouth","3":"Dispel Magic","4":"Imbue with Spell Ability","5":"Spell Resistance","6":"Antimagic Field","7":"Spell Turning","8":"Protection from Spells","9":"Mage's Disjunction"},"subdomainNames":["Alchemy","Arcane","Divine","Rites"],"subdomains":{"Alchemy":{"grantedPowers":[{"name":"Divine Alchemy","type":"Su","level":1,"text":"You can perform a 1-minute ritual that infuses a flask of water with one of your prepared spells, creating an improvised potion that lasts until consumed or the next time you prepare spells. You can use this ability only with spells that target one or more creatures, and the maximum spell level you can infuse in this way is equal to 1 + 1 for every 4 cleric levels you have. These potions are treated as alchemist extracts for the purpose of your domain spells. You can use this ability a number of times per day equal to 3 + your Wisdom modifier."}],"domainSpells":{}},"Arcane":{"grantedPowers":[{"name":"Arcane Beacon","type":"Su","level":1,"text":"As a standard action you can become a beacon of arcane energy until the end of your next turn. The aura emanates 15 feet from you. All arcane spells cast within the aura either gain a +1 bonus to their caster level or increase their saving throw DC by +1. The caster chooses the benefit when she casts the spell. You can use this ability a number of times per day equal to 3 + your Wisdom modifier."}],"domainSpells":{}},"Divine":{"grantedPowers":[{"name":"Divine Vessel","type":"Su","level":1,"text":"Whenever you are the target of a divine spell, you can, as a swift action, grant each ally within 15 feet of you a divine boon. This boon grants a +2 bonus on the next attack roll, skill check, or ability check made before the end of their next turn. You can use this ability a number of times per day equal to 3 + your Wisdom modifier."}],"domainSpells":{}},"Rites":{"grantedPowers":[{"name":"Enduring Ritual","type":"Su","level":1,"text":"As a swift action when you cast a spell with a duration of at least 1 minute per caster level, you can increase the spell's effective caster level by 1 for the purpose of determining its duration and preventing attempts to dispel it. The effective caster level increases by an additional 1 for every 10 cleric levels you have (maximum +3). You can use this ability a number of times per day equal to 3 + your Wisdom modifier."}],"domainSpells":{}}}},"Nobility":{"grantedPowers":[{"name":"Inspiring Word","type":"Sp","level":1,"text":"As a standard action, you can speak an inspiring word to a creature within 30 feet. That creature receives a +2 morale bonus on attack rolls, skill checks, ability checks, and saving throws for a number of rounds equal to 1/2 your cleric level (minimum 1). You can use this power a number of times per day equal to 3 + your Wisdom modifier."},{"name":"Leadership","type":"Ex","level":8,"text":"At 8th level, you receive Leadership as a bonus feat. In addition, you gain a +2 bonus on your leadership score as long as you uphold the tenets of your deity (or divine concept if you do not venerate a deity)."}],"domainSpells":{"1":"Divine Favor","2":"Enthrall","3":"Magic Vestment","4":"Discern Lies","5":"Greater Command","6":"Geas/Quest","7":"Repulsion","8":"Demand","9":"Storm of Vengeance"},"subdomainNames":["Aristocracy","Hubris","Leadership","Martyr"],"subdomains":{"Aristocracy":{"grantedPowers":[{"name":"Noble Visage","type":"Su","level":1,"text":"You gain a +1 bonus on Charisma checks and Charisma-based skill checks against creatures that share your creature type (and subtype, if you are a humanoid). This bonus increases by 1 for every 5 levels you possess. As a standard action, you can touch an ally to grant her your noble visage bonus against creatures that share her creature type (or subtype) for 1 minute. When you use this ability, you lose your noble visage bonus for 1 minute. You can use this ability a number of times per day equal to 3 + your Wisdom modifier."}],"domainSpells":{}},"Hubris":{"grantedPowers":[{"name":"Divine Demand","type":"Su","level":6,"text":"At 6th level, you can petition your divine patron for far greater power than you deserve. Activating this ability is a swift action that you must use as you cast a spell that has a reduced (but not negated) effect on a successful save. The saving throw DC of the spell increases by 2, and you gain a +2 bonus on caster level checks to overcome spell resistance with the spell. Any creature that succeeds at the saving throw instead avoids the effect entirely. If half or more of the targets are unaffected, you become shaken for a number of rounds equal to the spell's level. If all of the targets are unaffected, you instead lose the ability to cast divine spells, channel energy, and use domain powers for 1d4+1 rounds; you can end this loss as a full-round action by loudly apologizing to your patron deity as a full-round action that provokes attacks of opportunity. You can use this ability once per day at 6th level, and one additional time per day for every 4 levels beyond 6th."}],"domainSpells":{}},"Leadership":{"grantedPowers":[{"name":"Inspiring Command","type":"Su","level":1,"text":"As a standard action, you can issue an inspiring command to your allies. The inspiring command affects one ally plus one additional ally for every three cleric levels you possess, who must all be within 30 feet of you. Affected allies gain a +2 insight bonus on attack rolls, AC, combat maneuver defense, and skill checks for 1 round. This is a language-dependant mind-affecting effect."}],"domainSpells":{}},"Martyr":{"grantedPowers":[{"name":"Sacrificial Bond","type":"Su","level":8,"text":"At 8th level, when an ally within 30 feet takes damage from an attack, you can, as an immediate action, transfer this damage to yourself. This power also transfers any effects that accompany the damage. The damage done to you cannot be reduced in any way. You can use this ability once per day at 8th level, plus on additional time per day at 14th level and 20th level."}],"domainSpells":{}}}},"Plant":{"grantedPowers":[{"name":"Wooden Fist","type":"Su","level":1,"text":"As a free action, your hands can become as hard as wood, covered in tiny thorns. While you have wooden fists, your unarmed strikes do not provoke attacks of opportunity, deal lethal damage, and gain a bonus on damage rolls equal to 1/2 your cleric level (minimum +1). You can use this ability for a number of rounds per day equal to 3 + your Wisdom modifier. These rounds do not need to be consecutive."},{"name":"Bramble Armor","type":"Su","level":6,"text":"At 6th level, you can cause a host of wooden thorns to burst from your skin as a free action. While bramble armor is in effect, any foe striking you with an unarmed strike or a melee weapon without reach takes 1d6 points of piercing damage + 1 point per two cleric levels you possess. You can use this ability for a number of rounds per day equal to your cleric level. These rounds do not need to be consecutive."}],"domainSpells":{"1":"Entangle","2":"Barkskin","3":"Plant Growth","4":"Command Plants","5":"Wall of Thorns","6":"Repel Wood","7":"Animate Plants","8":"Control Plants","9":"Shambler"},"subdomainNames":["Decay","Growth","Leshy","Thorns"],"subdomains":{"Decay":{"grantedPowers":[{"name":"Aura of Decay","type":"Su","level":8,"text":"At 8th level, you can emit a 30-foot aura of decay as a standard action. Living creatures in this aura (except you) take 1d6 points of damage per round as their flesh rots. They also take a cumulative –1 penalty to Strength each round they remain in the aura. Once outside the aura, the penalty fades at the rate of –1 per round, but it begins building again if they reenter the aura. Plant creatures take 2d6 points of damage per round. You can use this ability for a number of rounds per day equal to your cleric level. These rounds do not need to be consecutive."}],"domainSpells":{}},"Growth":{"grantedPowers":[{"name":"Enlarge","type":"Su","level":1,"text":"As a swift action you can enlarge yourself for 1 round, as if you were the target of the enlarge person spell. You can use this ability a number of times per day equal to 3 + your Wisdom modifier."}],"domainSpells":{}},"Leshy":{"grantedPowers":[{"name":"Leshy Caller","type":"Sp","level":1,"text":"You can spontaneously swap out any of your domain spells for a summon nature's ally spell of the same level or lower, to a maximum of summon nature's ally VII. If you do, you must use the spell to summon one or more leshys. Add leaf leshy, gourd leshy, fungus leshy, seaweed leshy, and lotus leshy to your summon nature's ally I, II, III, IV, and V lists, respectively. You count as a plant creature for the purpose of creating leshys (Pathfinder RPG Bestiary 3 176). As a standard action, you can grant a single leshy within 30 feet a +4 sacred bonus on its next attack roll before the start of your next turn. You can use this ability a number of times per day equal to 3 + your Wisdom modifier."}],"domainSpells":{}},"Thorns":{"grantedPowers":[{"name":"Cruel Thicket","type":"Su","level":1,"text":"As a standard action, you can cause the ground in a 5-foot-radius burst centered on you to sprout twisting, thorny vines. Any creature moving through it must travel at half speed or take bleed damage equal to half your cleric level; if you activate this ability in an area with numerous plants (grass, weeds, trees, etc.), the area also becomes difficult terrain. These effects last for 1 minute, after which the vines crumble to dust. Creatures able to move through natural undergrowth unhindered ignore the effects of this ability. You can use this ability a number of times per day equal to 3 + your Wisdom modifier."}],"domainSpells":{}}}},"Protection":{"grantedPowers":[{"name":"Resistant Touch","type":"Sp","level":1,"text":"As a standard action, you can touch an ally to grant him your resistance bonus for 1 minute. When you use this ability, you lose your resistance bonus granted by the Protection domain for 1 minute. You can use this ability a number of times per day equal to 3 + your Wisdom modifier."},{"name":"Aura of Protection","type":"Su","level":8,"text":"At 8th level, you can emit a 30-foot aura of protection for a number of rounds per day equal to your cleric level. You and your allies within this aura gain a +1 deflection bonus to AC and resistance 5 against all elements (acid, cold, electricity, fire, and sonic). The deflection bonus increases by +1 for every four cleric levels you possess beyond 8th. At 14th level, the resistance against all elements increases to 10. These rounds do not need to be consecutive."}],"domainSpells":{"1":"Sanctuary","2":"Shield Other","3":"Protection from Energy","4":"Spell Immunity","5":"Spell Resistance","6":"Antimagic Field","7":"Repulsion","8":"Mind Blank","9":"Prismatic Sphere"},"subdomainNames":["Defense","Fortifications","Purity","Solitude"],"subdomains":{"Defense":{"grantedPowers":[{"name":"Deflection Aura","type":"Su","level":1,"text":"Once each day, you can emit a 20-foot aura for a number of rounds equal to your cleric level. Allies within the aura gain a +2 deflection bonus to AC and combat maneuver defense."}],"domainSpells":{}},"Fortifications":{"grantedPowers":[{"name":"Sheltering Walls","type":"Sp","level":1,"text":"As a standard action, you can touch an ally to summon a floating blockade of stone, granting the ally the benefits of partial cover for 1 round plus 1 round for every 6 cleric levels you possess. This ability does not grant the ally enough cover to attempt a Stealth check or avoid provoking attacks of opportunity. If the ally benefits from any other form of cover against an attack, the bonuses to AC and on Reflex saving throws increase by 1. You can use this power a number of times per day equal to 3 + your Wisdom modifier."}],"domainSpells":{}},"Purity":{"grantedPowers":[{"name":"Purifying Touch","type":"Su","level":8,"text":"At 8th level, you can touch a willing creature with divine power, giving it a saving throw against each effect currently affecting it, using the original saving throw DC of the effect. Each successful saving throw ends the related effect. The creature can choose not to make a save against an effect. You can use this ability once per day at 8th level, plus one additional time per day at 14th and 20th level."}],"domainSpells":{}},"Solitude":{"grantedPowers":[{"name":"Taboo","type":"Su","level":1,"text":"When a creature touches you or strikes you with a melee attack, you can activate this power as an immediate action. That creature takes a –1 penalty on saving throws for 1 minute. This penalty increases by 1 for every 5 levels you possess. When you use this ability, you lose your resistance bonus granted by the Protection domain for 1 minute. You can use this ability a number of times per day equal to 3 + your Wisdom modifier."}],"domainSpells":{}}}},"Repose":{"grantedPowers":[{"name":"Gentle Rest","type":"Sp","level":1,"text":"Your touch can fill a creature with lethargy, causing a living creature to become staggered for 1 round as a melee touch attack. If you touch a staggered living creature, that creature falls asleep for 1 round instead. Undead creatures touched are staggered for a number of rounds equal to your Wisdom modifier. You can use this ability a number of times per day equal to 3 + your Wisdom modifier."},{"name":"Ward Against Death","type":"Su","level":8,"text":"At 8th level, you can emit a 30-foot aura that wards against death for a number of rounds per day equal to your cleric level. Living creatures in this area are immune to all death effects, energy drain, and effects that cause negative levels. This ward does not remove negative levels that a creature has already gained, but the negative levels have no effect while the creature is inside the warded area. These rounds do not need to be consecutive."}],"domainSpells":{"1":"Deathwatch","2":"Gentle Repose","3":"Speak with Dead","4":"Death Ward","5":"Slay Living","6":"Undeath to Death","7":"Destruction","8":"Waves of Exhaustion","9":"Wail of the Banshee"},"subdomainNames":["Ancestors","Psychopomp","Souls"],"subdomains":{"Ancestors":{"grantedPowers":[{"name":"Speak With Dead","type":"Su","level":8,"text":"At 8th level, as a standard action, you can ask one question of a dead creature as if using speak with dead. The dead creature you are questioning does not gain a Will saving throw if your alignments are different. You can use this ability a number of times per day equal to your cleric level."}],"domainSpells":{}},"Psychopomp":{"grantedPowers":[{"name":"Spirit Touch","type":"Su","level":6,"text":"At 6th level, as a swift action, you can give your natural weapons or any weapons you wield the ghost touch weapon special ability. You can use this power a number of rounds per day equal to your cleric level. These rounds need not be consecutive."}],"domainSpells":{}},"Souls":{"grantedPowers":[{"name":"Touch the Spirit World","type":"Su","level":1,"text":"With a touch, you can empower a weapon to affect incorporeal creatures. The weapon touched deals half damage to incorporeal creatures, or full damage if it is a magic weapon. This benefit lasts for a number of rounds equal to your cleric level. You can use this ability a number of times per day equal to 3 + your Wisdom modifier."}],"domainSpells":{}}}},"Ruins":{"grantedPowers":[{"name":"Ruin Touch","type":"Su","level":1,"text":"You can strengthen or weaken objects with your touch. With a melee touch attack, you can increase or decrease the hardness of an object (up to a 10-foot cube) or construct by an amount equal to half your druid level (minimum 1) for 1 minute. You cannot reduce an object's hardness below 0, and the same target cannot be affected by this ability more than once. You can use this ability a number of times per day equal to 3 + your Wisdom modifier."},{"name":"Remembrance","type":"Sp","level":4,"text":"At 4th level, when within a ruin or other structure that is no longer claimed by civilization, you can call upon the wisdom of the land and its long-dead residents. Once per day for every 4 druid levels you possess, you can cast divination as a spell-like ability. Additionally, if you are within ruins when you cast commune with nature, you gain information about the crumbling structures around you as though they were part of nature."},{"name":"Surefooted","type":"Ex","level":8,"text":"At 8th level, your speed is not reduced by difficult terrain unless the terrain has been magically manipulated to impede motion."}],"domainSpells":{"1":"Magic Stone","2":"Stone Call","3":"Meld into Stone","4":"Rusting Grasp","5":"Commune with Nature","6":"Stone Tell","7":"Statue","8":"Earthquake","9":"Clashing Rocks"},"subdomainNames":[],"subdomains":{}},"Rune":{"grantedPowers":[{"name":"Blast Rune","type":"Sp","level":1,"text":"As a standard action, you can create a blast rune in any adjacent square. Any creature entering this square takes 1d6 points of damage + 1 point for every two cleric levels you possess. This rune deals either acid, cold, electricity, or fire damage, decided when you create the rune. The rune is invisible and lasts a number of rounds equal to your cleric level or until discharged. You cannot create a blast rune in a square occupied by another creature. This rune counts as a 1st-level spell for the purposes of dispelling. It can be discovered with a DC 26 Perception skill check and disarmed with a DC 26 Disable Device skill check. You can use this ability a number of times per day equal to 3 + your Wisdom modifier."},{"name":"Spell Rune","type":"Sp","level":8,"text":"At 8th level, you can attach another spell that you cast to one of your blast runes, causing that spell to affect the creature that triggers the rune, in addition to the damage. This spell must be of at least one level lower than the highest-level cleric spell you can cast and it must target one or more creatures. Regardless of the number of targets the spell can normally affect, it only affects the creature that triggers the rune."}],"domainSpells":{"1":"Erase","2":"Secret Page","3":"Glyph of Warding","4":"Explosive Runes","5":"Lesser Planar Binding","6":"Greater Glyph of Warding","7":"Instant Summons","8":"Symbol of Death","9":"Teleportation Circle"},"subdomainNames":["Language","Legislation","Wards"],"subdomains":{"Language":{"grantedPowers":[{"name":"Rune Shift","type":"Su","level":6,"text":"At 6th level, as a swift action, you can change the location of one of your blast runes. The rune must be within 30 feet. You can place the blast rune in any square adjacent to you, including one occupied by another creature."}],"domainSpells":{}},"Legislation":{"grantedPowers":[{"name":"Prohibition","type":"Su","level":1,"text":"As a standard action, you can command a creature within 30 feet to refrain from committing a particular action (including any referenced in the spell forbid action). If the creature performs the named action before the beginning of your next turn, it takes 1d6 points of damage + 1 point for every 2 cleric levels you possess and the effect ends. This is a language-dependent effect. You can use this ability a number of times per day equal to 3 + your Wisdom modifier.\n\nIf you have the spell rune domain power, you can attach a spell effect to the prohibition as if it were the spell rune domain ability; the spell takes effect if the creature performs the named action. This spell must be of at least 1 level lower than the highest-level cleric spell you can cast, and it must target one or more creatures. Regardless of the number of targets the spell can normally affect, it affects only the creature that triggers the rune. Attaching a spell in this way extends the duration of the prohibition by a number of rounds equal to the spell's level, or until it is discharged."}],"domainSpells":{}},"Wards":{"grantedPowers":[{"name":"Warding Rune","type":"Su","level":6,"text":"At 6th level, when a creature is damaged by your blast rune, it cannot attack you for a number of rounds equal to 1/2 your cleric level unless it succeeds at a Will save, as per the spell sanctuary. Using this ability is an immediate action when a creature triggers one of your blast runes. The ability does not prevent you from being attacked or affected by area of effect spells or abilities. You can use this ability once per day at 8th level, plus one additional time per day at 14th level and 20th level."}],"domainSpells":{}}}},"Scalykind":{"grantedPowers":[{"name":"Venemous Stare","type":"Sp","level":1,"text":"As a standard action, you can activate a gaze attack with a 30-foot range. This is an active gaze attack that can target a single creature within range. The target must make a Will save (DC = 10 + 1/2 your cleric level + your Wisdom modifier). Those that fail take 1d6 points of nonlethal damage + 1 point for every two cleric levels you possess and are fascinated until the beginning of your next turn. You can use this ability a number of times per day equal to 3 + your Wisdom modifier. This is a mind-affecting effect."},{"name":"Serpent Companion","type":"Ex","level":4,"text":"At 4th level, you gain the service of an animal companion. Your effective druid level for this animal companion is equal to your cleric level –2. You may choose either a viper or a constrictor snake as your companion."}],"domainSpells":{"1":"Magic Fang","2":"Animal Trance","3":"Greater Magic Fang","4":"Poison","5":"Animal Growth (reptiles only)","6":"Eyebite","7":"Creeping Doom (takes the form of diminutive-sized reptiles)","8":"Animal Shapes (reptiles only)","9":"Shapechange (reptiles only)"},"subdomainNames":["Dragon","Saurian","Venom"],"subdomains":{"Dragon":{"grantedPowers":[{"name":"Dragonbreath","type":"Su","level":4,"text":"At 4th level, you can use a breath weapon once per day as a standard action. When you gain this ability, choose what kind of damage your breath weapon deals: acid, cold, electricity, or fire. Once you make this choice, you can't change it later. Your breath weapon fills a 15-foot cone and deals 3d6 points of damage; this damage increases by 1d6 points at every even-numbered level you gain beyond 4th level. A creature hit by your dragonbreath attack can attempt a Reflex save (DC = 10 + half your class level + your Wisdom modifier) to take half damage. At 9th level, you can use this ability two times per day, and at 14th level, you can use it three times per day."}],"domainSpells":{}},"Saurian":{"grantedPowers":[{"name":"Dinosaur Companion","type":"Ex","level":4,"text":"At 4th level, you gain the service of a loyal animal companion. Your effective druid level for the purpose of this animal companion is equal to your class level – 2. You must choose a dinosaur as your companion."}],"domainSpells":{}},"Venom":{"grantedPowers":[{"name":"Venomous Saliva","type":"Su","level":1,"text":"Just as certain serpents can spray poison from their fangs, as a swift action, you can spit a gout of life-stealing venom onto a weapon you are wielding. The poison lasts for 1 minute or until you make an attack with that weapon that injures a foe. Life-Stealing Venom: Injury; save Fort DC 10 + half your class level + your Wisdom modifier; frequency 1/round for 3 rounds; effect 1 Con damage; cure 1 save. You can use the venomous saliva ability a number of times per day equal to 3 + your Wisdom modifier."}],"domainSpells":{}}}},"Strength":{"grantedPowers":[{"name":"Strength Surge","type":"Sp","level":1,"text":"As a standard action, you can touch a creature to give it great strength. For 1 round, the target gains an enhancement bonus equal to 1/2 your cleric level (minimum +1) to melee attacks, combat maneuver checks that rely on Strength, Strength-based skills, and Strength checks. You can use this ability a number of times per day equal to 3 + your Wisdom modifier."},{"name":"Might of the Gods","type":"Su","level":8,"text":"At 8th level, you can add your cleric level as an enhancement bonus to your Strength score for a number of rounds per day equal to your cleric level. This bonus only applies on Strength checks and Strength-based skill checks. These rounds do not need to be consecutive."}],"domainSpells":{"1":"Enlarge Person","2":"Bull's Strength","3":"Magic Vestment","4":"Spell Immunity","5":"Righteous Might","6":"Stoneskin","7":"Grasping Hand","8":"Clenched Fist","9":"Crushing Hand"},"subdomainNames":["Competition","Ferocity","Fist","Resolve","Self-Realization"],"subdomains":{"Competition":{"grantedPowers":[{"name":"Athletic Exploit","type":"Su","level":1,"text":"As a swift action, you gain the ability to overcome physical obstacles with ease. Until the beginning of your next turn, you halve your armor check penalty when attempting Acrobatics, Climb, Escape Artist, and Swim skill checks, and you gain a bonus equal to 1/2 your cleric level (minimum +1) on such skill checks."}],"domainSpells":{}},"Ferocity":{"grantedPowers":[{"name":"Ferocious Strike","type":"Su","level":1,"text":"Whenever you make a melee attack, you can designate that attack as a ferocious strike. If the attack hits, it deals additional damage equal to 1/2 your cleric level (minimum +1). You can use this ability a number of times per day equal to 3 + your Wisdom modifier."}],"domainSpells":{}},"Fist":{"grantedPowers":[{"name":"Wooden Fist","type":"Su","level":1,"text":"As a free action, your hands can become as hard as wood, covered in tiny thorns. While you have wooden fists, your unarmed strikes do not provoke attacks of opportunity, deal lethal damage, and gain a bonus on damage rolls equal to 1/2 your cleric level (minimum +1). You can use this ability for a number of rounds per day equal to 3 + your Wisdom modifier. These rounds do not need to be consecutive."}],"domainSpells":{}},"Resolve":{"grantedPowers":[{"name":"Bestow Resolve","type":"Su","level":8,"text":"At 8th level, you can bless creatures with the boldness of your deity. You can bestow a number of temporary hit points equal to your level + your Wisdom modifier to all allies within 20 feet. The temporary hit points remain for 1 minute. You can use this ability once per day at 8th level, plus one additional time per day for every 4 levels you possess beyond 8th."}],"domainSpells":{}},"Self-Realization":{"grantedPowers":[{"name":"Perfected Form","type":"Su","level":1,"text":"You maintain an unshakable sense of who you are, and no force can compel you to be anything else. You gain a +1 sacred (if your patron is good or neutral) or profane (if your patron is evil) bonus on saving throws against polymorph, petrification, and transmutation effects. This bonus increases by 1 for every 5 cleric levels you have (maximum +5). Once per day when you succeed at a saving throw against such an effect, you can gain a surge of self-confidence as an immediate action that grants you a number of temporary hit points equal to your cleric level and a +2 morale bonus on attack rolls, skill checks, and saving throws; both effects last for 1 minute."}],"domainSpells":{}}}},"Sun":{"grantedPowers":[{"name":"Sun's Blessing","type":"Su","level":1,"text":"Whenever you channel positive energy to harm undead creatures, add your cleric level to the damage dealt. Undead do not add their channel resistance to their saves when you channel positive energy."},{"name":"Nimbus of Light","type":"Su","level":8,"text":"At 8th level, you can emit a 30-foot nimbus of light for a number of rounds per day equal to your cleric level. This acts as a daylight spell. In addition, undead within this radius take an amount of damage equal to your cleric level each round that they remain inside the nimbus. Spells and spell-like abilities with the darkness descriptor are automatically dispelled if brought inside this nimbus. These rounds do not need to be consecutive."}],"domainSpells":{"1":"Endure Elements","2":"Heat Metal","3":"Searing Light","4":"Fire Shield","5":"Flame Strike","6":"Fire Seeds","7":"Sunbeam","8":"Sunburst","9":"Prismatic Sphere"},"subdomainNames":["Day","Light","Revelation","Thirst"],"subdomains":{"Day":{"grantedPowers":[{"name":"Day's Resurgence","type":"Su","level":8,"text":"At 8th level, you can restore a single creature as if it had just completed 8 hours of rest. It takes 10 minutes to use this power. If the use of this power is disrupted, it must be restarted, but it is not lost. At the end of the 10 minutes, a single willing creature that you have touched regains hit points as if it had rested for the night and may make new saving throws against effects that require a save once per day. The target does not suffer any negative effects if such saving throws are failed, but success counts toward removing the affliction (if possible). This ability does not allow a target to prepare spells an additional time per day. You can use this ability once per day at 8th level, plus one additional time per day for every 2 levels beyond 8th."}],"domainSpells":{}},"Light":{"grantedPowers":[{"name":"Blinding Flash","type":"Su","level":1,"text":"As a standard action, you can emit a flash of light from your holy symbol or divine focus. The most powerful light emanates out 20 feet from you. Creatures with fewer Hit Dice than your cleric level within this area are blinded for 1d4 rounds unless they succeed at a Fortitude save. All creatures in this area are dazzled for a number of rounds equal to 1/2 your cleric level (minimum 1). You can use this ability a number of times per day equal to 3 + your Wisdom modifier."}],"domainSpells":{}},"Revelation":{"grantedPowers":[{"name":"Guided Eyes","type":"Su","level":1,"text":"Perception is always a class skill for you. In addition, whenever you make a skill check to see through a disguise or find something that is hidden or concealed, you gain a +4 sacred bonus on the check."}],"domainSpells":{}},"Thirst":{"grantedPowers":[{"name":"Wilting Glare","type":"Su","level":1,"text":"As a standard action, you can leach moisture and vitality from a living, corporeal creature you can see within 30 feet. The target takes an amount of nonlethal damage equal to 1d6 + 1 for every 2 cleric levels you have and becomes fatigued until the beginning of your next turn (Fortitude negates). Plant creatures and those with the aquatic or water subtype take lethal damage from this ability, and they are fatigued for a number of rounds equal to your Wisdom modifier. You can use this ability a number of times per day equal to 3 + your Wisdom modifier."},{"name":"Withering Nimbus","type":"Su","level":8,"text":"This ability functions as the nimbus of light domain ability, but it damages plants and creatures with the aquatic or water subtype, not undead."}],"domainSpells":{}}}},"Travel":{"grantedPowers":[{"name":"Agile Feet","type":"Su","level":1,"text":"As a free action, you can gain increased mobility for 1 round. For the next round, you ignore all difficult terrain and do not take any penalties for moving through it. You can use this ability a number of times per day equal to 3 + your Wisdom modifier."},{"name":"Dimensional Hop","type":"Sp","level":8,"text":"At 8th level, you can teleport up to 10 feet per cleric level per day as a move action. This teleportation must be used in 5-foot increments and such movement does not provoke attacks of opportunity. You must have line of sight to your destination to use this ability. You can bring other willing creatures with you, but you must expend an equal amount of distance for each creature brought."}],"domainSpells":{"1":"Longstrider","2":"Locate Object","3":"Fly","4":"Dimension Door","5":"Teleport","6":"Find the Path","7":"Greater Teleport","8":"Phase Door","9":"Astral Projection"},"subdomainNames":["Exploration","Portal","Trade"],"subdomains":{"Exploration":{"grantedPowers":[{"name":"Door Sight","type":"Su","level":1,"text":"You can lay your hand upon any surface and see what is on the other side, as if using clairvoyance. Using this power takes 1 minute, during which time you must be touching the surface you want to see through. You can keep looking for as long as 10 minutes with each use of this power, but must touch the surface and take no other action the entire time. The surface cannot be thicker than 6 inches plus 1 inch per cleric level you possess. You can use this power a number of times per day equal to 3 + your Wisdom modifier."}],"domainSpells":{}},"Portal":{"grantedPowers":[{"name":"Sacred Threshold","type":"Su","level":1,"text":"As a standard action, you can bless a door, a window, or another portal with a touch. For 1 minute, you can increase or decrease the DC of any check to unlock or force open the portal by an amount equal to half your cleric level. In addition, your first ally to pass through the portal during this time gains an amount of temporary hit points equal to 1d4 + 1 for every 2 cleric levels you have. These temporary hit points last for 1 minute. You can use this ability a number of times per day equal to 3 + your Wisdom modifier."},{"name":"Travel as One","type":"Su","level":1,"text":"When you cast a spell with the teleportation descriptor, treat your caster level as 3 higher for the purpose of determining how many additional creatures you can bring with you. In addition, you and any creatures you teleport gain a number of temporary hit points equal to your level that disappear after you reach your destination; these offset any damage you might take from teleportation mishaps or attempting to teleport into a solid body."}],"domainSpells":{}},"Trade":{"grantedPowers":[{"name":"Silver-Tongued Haggler","type":"Su","level":1,"text":"Whenever you make a Bluff, Diplomacy, or Sense Motive check, you can, as a free action, grant yourself a bonus on the roll equal to 1/2 your cleric level (minimum +1). You can use this ability a number of times per day equal to 3 + your Wisdom modifier."}],"domainSpells":{}}}},"Trickery":{"grantedPowers":[{"name":"Copycat","type":"Sp","level":1,"text":"You can create an illusory double of yourself as a move action. This double functions as a single mirror image and lasts for a number of rounds equal to your cleric level, or until the illusory duplicate is dispelled or destroyed. You can have no more than one copycat at a time. This ability does not stack with the mirror image spell. You can use this ability a number of times per day equal to 3 + your Wisdom modifier."},{"name":"Master's Illusion","type":"Sp","level":8,"text":"At 8th level, you can create an illusion that hides the appearance of yourself and any number of allies within 30 feet for 1 round per cleric level. This ability otherwise functions like the spell veil. The save DC to disbelieve this effect is equal to 10 + 1/2 your cleric level + your Wisdom modifier. The rounds do not need to be consecutive."}],"domainSpells":{"1":"Disguise Self","2":"Invisibility","3":"Nondetection","4":"Confusion","5":"False Vision","6":"Mislead","7":"Screen","8":"Mass Invisibility","9":"Time Stop"},"subdomainNames":["Ambush","Deception","Espionage","Greed","Innuendo","Thievery"],"subdomains":{"Ambush":{"grantedPowers":[{"name":"Chameleon Aspect","type":"Su","level":1,"text":"As a swift action, you can subtly alter the color of your scales, blending them with the surrounding environment. While under the effect of this power, you gain concealment from creatures more than 10 feet away (attacks have a 20% miss chance), and total concealment from creatures more than 40 feet away (attacks have a 50% miss chance). You can use this ability a number of rounds per day equal to 3 + your Wisdom modifier."}],"domainSpells":{}},"Deception":{"grantedPowers":[{"name":"Sudden Shift","type":"Sp","level":1,"text":"In the blink of an eye, you can appear somewhere else. As an immediate action, after you are missed by a melee attack, you can teleport up to 10 feet to a space that you can see. This space must be inside the reach of the creature that attacked you. You can use this power a number of times each day equal to 3 + your Wisdom modifier."}],"domainSpells":{}},"Espionage":{"grantedPowers":[{"name":"Deep Cover","type":"Su","level":1,"text":"When you prepare your spells, you can also choose one cover identity-whether that of a real person or a fictitious one. You can assume the disguise of your cover identity in half the normal amount of time. When targeted by a spell or effect that would compromise your chosen disguise (such as detect evil, detect thoughts, or zone of truth), as an immediate action you can force the creature using the ability to attempt a Will save (DC = 10 + 1/2 your cleric level + your Wisdom modifier). If the creature fails, it gains false information in keeping with your cover identity. You can use this false information ability a number of times per day equal to 3 + your Wisdom modifier."}],"domainSpells":{}},"Greed":{"grantedPowers":[{"name":"More for Me","type":"Su","level":1,"text":"When another character within 30 feet casts a spell with a range greater than touch, you can attempt a caster level check as an immediate action (DC = 15 + the spell's level). If you succeed at the check, you receive the spell's benefit instead of one of the spell's intended targets (chosen by you). If you are already a target of the spell, you are affected as though you were targeted by the same spell twice (which may or may not benefit you; remember that bonuses from the same source do not stack). This ability does not grant you knowledge of the spell being cast. You can use this ability a number of times per day equal to 3 + your Wisdom modifier."}],"domainSpells":{}},"Innuendo":{"grantedPowers":[{"name":"Fool's Privilege","type":"Su","level":1,"text":"You can use this power as a swift action when you fail a Bluff, Diplomacy, or Intimidate check outside of combat. You suffer no negative effects due to the failed check, and the next round you can attempt the check again without the usual penalty for a failed attempt. You can use this ability once per day, and one additional time per day for every 4 levels beyond 1st."}],"domainSpells":{}},"Thievery":{"grantedPowers":[{"name":"Thief of the Gods","type":"Su","level":8,"text":"At 8th level, when you make a Disable Device or Sleight of Hand check, you can roll twice and take the higher result. Using this ability is a free action. You can use this ability once per day at 8th level, plus one additional time per day for every 2 levels beyond 8th."}],"domainSpells":{}}}},"Vermin":{"grantedPowers":[{"name":"Familiar","type":"Consultar manual","level":1,"text":"You gain a greensting scorpion familiar. Your effective wizard level for this ability is equal to your druid level. Your druid level stacks with levels from other classes that grant familiars when determining the powers of your familiar."},{"name":"Vermin Friend","type":"Ex","level":1,"text":"You can use wild empathy to influence vermin as easily as you influence animals if you do not already possess this ability."},{"name":"Tremorsense","type":"Ex","level":6,"text":"At 6th level, you gain tremorsense 30 feet. At 12th level, you gain tremorsense 60 feet."}],"domainSpells":{"1":"Jump","2":"Vomit Swarm","3":"Darkvision","4":"Insect Plague","5":"Swarm Skin (spider, crab, centipede, and army ant swarms only)","6":"Whip of Ants","7":"Creeping Doom","8":"Mass Fly","9":"Mind Blank"},"subdomainNames":[],"subdomains":{}},"Vermin (Ultimate Wilderness)":{"grantedPowers":[{"name":"Vermin Whisperer","type":"Su","level":1,"text":"You can use your wild empathy ability on vermin. When you do so, you impart a modicum of implanted intelligence on the vermin, allowing you to interact with vermin as if they were animals. Vermin whisperer functions only on vermin that are mindless or have an Intelligence score of 2 or lower."},{"name":"Sudden Sting","type":"Su","level":8,"text":"At 8th level, you can inflict a lingering, painful sting as a swift action that requires a successful melee touch attack. This sting deals 1d4 points of piercing damage plus 1 point for every 2 druid levels you have, and the target must succeed at a Fortitude save (DC = 10 + half your druid level + your Constitution modifier) or become staggered for 1 round. This is a pain effect. You can use this ability a number of times per day equal to 3 + your Wisdom modifier."}],"domainSpells":{"1":"Ant Haul","2":"Summon Swarm","3":"Vermin Shape I","4":"Vermin Shape II","5":"Insect Plague","6":"Swarm Skin","7":"Creeping Doom","8":"Verminous Transformation","9":"Summon Nature's Ally IX (1d3 purple worms only)"},"subdomainNames":[],"subdomains":{}},"Void":{"grantedPowers":[{"name":"Guarded Mind","type":"Ex","level":1,"text":"You gain a +2 insight bonus on saving throws against all mind-affecting effects."},{"name":"Part the Veil","type":"Su","level":8,"text":"At 8th level, you can imbue the spells you cast with the raw madness that waits in the outer darkness. Activating this ability is a swift action that you must use as you cast a spell that targets a single creature and that allows a Will saving throw to negate or reduce the spell's primary effect. If the target fails to resist the spell, the target is also confused for a number of rounds equal to the spell's level as visions of the void cause temporary insanity. The victim must succeed at a new saving throw each round to end the effect - these additional saving throws apply only to the additional confusion effect and not to the original spell effect. Part the veil is a mind-affecting effect. You can use this ability a number of times per day equal to 1/2 your class level."}],"domainSpells":{"1":"Feather Fall","2":"Levitate","3":"Fly","4":"Lesser Planar Binding","5":"Overland Flight","6":"Planar Binding","7":"Reverse Gravity","8":"Greater Planar Binding","9":"Interplanetary Teleport"},"subdomainNames":["Dark Tapestry","Isolation","Stars"],"subdomains":{"Dark Tapestry":{"grantedPowers":[{"name":"It Came from Beyond","type":"Su","level":1,"text":"Once per day when you cast a summoning spell, any one creature you summon is more powerful than normal. The creature gains the advanced creature simple template. If you summon more than one creature with a spell, only one of the summoned creatures gains the advanced creature simple template. A summoned creature that gains the advanced creature simple template in this manner looks unusually deformed or hideous. This ability only works on spells you cast as a cleric - it does not work on spellcasting abilities gained from any other spellcasting classes you might have."}],"domainSpells":{}},"Isolation":{"grantedPowers":[{"name":"Aura of Isolation","type":"Su","level":8,"text":"As a standard action, you can create a 20-foot aura that causes enemies within to be overcome with feelings of isolation and loss. Your enemies treat the aura as difficult terrain, as they become sluggish within its area of effect. Furthermore, while within the aura, your enemies can't flank with one another, nor can they use or benefit from the aid another action. The aura lasts for a number of rounds equal to 3 + your Wisdom modifier, but the rounds need not be consecutive. This is a mind-affecting emotion effect."}],"domainSpells":{}},"Stars":{"grantedPowers":[{"name":"The Stars Are Right","type":"Su","level":8,"text":"If you prepare your cleric spells while the stars are visible to you, you may spontaneously cast any of your Stars subdomain domain spells by swapping out a spell of an equal spell level. Any Stars subdomain spells that you cast while the stars are visible to you heal you of damage equal to the spell's level as you cast the spell."}],"domainSpells":{}}}},"War":{"grantedPowers":[{"name":"Battle Rage","type":"Sp","level":1,"text":"You can touch a creature as a standard action to give it a bonus on melee damage rolls equal to 1/2 your cleric level for 1 round (minimum +1). You can do so a number of times per day equal to 3 + your Wisdom modifier."},{"name":"Weapon Master","type":"Su","level":8,"text":"At 8th level, as a swift action, you gain the use of one combat feat for a number of rounds per day equal to your cleric level. These rounds do not need to be consecutive and you can change the feat chosen each time you use this ability. You must meet the prerequisites to use this feat."}],"domainSpells":{"1":"Magic Weapon","2":"Spiritual Weapon","3":"Magic Vestment","4":"Divine Power","5":"Flame Strike","6":"Blade Barrier","7":"Power Word Blind","8":"Power Word Stun","9":"Power Word Kill"},"subdomainNames":["Blood","Duels","Tactics"],"subdomains":{"Blood":{"grantedPowers":[{"name":"Wounding Blade","type":"Su","level":8,"text":"At 8th level, you can give a weapon that you touch the wounding special weapon quality for a number of rounds equal to 1/2 your cleric level. You can use this ability once per day at 8th level, and an additional time per day for every four levels beyond 8th."}],"domainSpells":{}},"Duels":{"grantedPowers":[{"name":"Divine Challenge","type":"Su","level":1,"text":"As a swift action, you can challenge a visible foe within 30 feet, gaining a +1 sacred bonus to your AC against that creature's attacks and a bonus equal to 1/2 your cleric level on Bluff skill checks to feint against it. These bonuses last for a number of rounds equal to 1/2 your cleric level. You can use this ability a number of times per day equal to 3 + your Wisdom modifier."}],"domainSpells":{}},"Tactics":{"grantedPowers":[{"name":"Seize the Initiative","type":"Su","level":1,"text":"Whenever you and your allies roll for initiative, you can grant one ally within 30 feet the ability to roll twice and take either result. This decision is made before results are revealed. You can use this ability a number of times per day equal to 3 + your Wisdom modifier."}],"domainSpells":{}}}},"Water":{"grantedPowers":[{"name":"Icicle","type":"Sp","level":1,"text":"As a standard action, you can fire an icicle from your finger, targeting any foe within 30 feet as a ranged touch attack. The icicle deals 1d6 points of cold damage + 1 point for every two cleric levels you possess. You can use this ability a number of times per day equal to 3 + your Wisdom modifier."},{"name":"Cold Resistance","type":"Ex","level":6,"text":"At 6th level, you gain resist cold 10. This resistance increases to 20 at 12th level. At 20th level, you gain immunity to cold."}],"domainSpells":{"1":"Obscuring Mist","2":"Fog Cloud","3":"Water Breathing","4":"Control Water","5":"Ice Storm","6":"Cone of Cold","7":"Elemental Body IV (water only)","8":"Horrid Wilting","9":"Elemental Swarm (water spell only)"},"subdomainNames":["Flotsam","Flowing","Ice","Oceans","Rivers"],"subdomains":{"Flotsam":{"grantedPowers":[{"name":"Sift","type":"Su","level":6,"text":"At 6th level, once per day you can reach into water as a standard action and pull out an object with a maximum gp value of up to 50 gp x your class level. This object always has the broken condition upon being withdrawn from the water. The water you reach into must be at least deep enough to fully immerse yourself in. At 12th level, the objects that you retrieve are not broken. At 20th level, you can retrieve objects worth up to 5,000 gp. If you're retrieving an object that would not normally float, assume it rests on top of or is entwined with debris that does float. Objects retrieved in this manner disappear after 24 hours if they're not already used up or otherwise destroyed before then."}],"domainSpells":{}},"Flowing":{"grantedPowers":[{"name":"Go with the Flow","type":"Su","level":1,"text":"You can touch a creature as a standard action to suppress its strong emotions. The target is affected as the calm emotions spell, except it can still take violent actions and violent actions against the target do not end the effect. This effect lasts a number of rounds equal to 1/2 your cleric level (minimum 1). You can use this ability a number times per day equal to 3 + your Wisdom modifier."}],"domainSpells":{}},"Ice":{"grantedPowers":[{"name":"Body of Ice","type":"Su","level":8,"text":"At 8th level, you can transmute your body and equipment to ice for a period of time. It takes a standard action to take on the form of ice, and you can end the transmutation with a free action on your turn. When you take on the form of ice, you are immune to cold and have DR 5/-, but you take twice the normal amount of damage from fire. You can take on the form of ice for a number of rounds per day equal to your cleric level. The rounds need not be consecutive."}],"domainSpells":{}},"Oceans":{"grantedPowers":[{"name":"Surge","type":"Su","level":1,"text":"As a standard action, you can cause a mighty wave to appear that pushes or pulls a single creature. Make a combat maneuver check against the target, using your cleric level + your Wisdom modifier as your CMB. If successful, you may pull or push the creature as if using the bull rush or drag combat maneuver. You can use this ability a number of times per day equal to 3 + your Wisdom modifier."}],"domainSpells":{}},"Rivers":{"grantedPowers":[{"name":"Current Flow","type":"Su","level":1,"text":"As a free action, you can increase either your base speed or your swim speed by 10 feet. While swimming, you gain a bonus on Swim checks equal to half your class level (minimum 1). These effects last for a number of rounds equal to your Wisdom modifier (minimum 1). You can use this ability a number of times per day equal to 3 + your Wisdom modifier."}],"domainSpells":{}}}},"Weather":{"grantedPowers":[{"name":"Storm Burst","type":"Sp","level":1,"text":"As a standard action, you can create a storm burst targeting any foe within 30 feet as a ranged touch attack. The storm burst deals 1d6 points of nonlethal damage + 1 point for every two cleric levels you possess. In addition, the target is buffeted by winds and rain, causing it to take a -2 penalty on attack rolls for 1 round. You can use this ability a number of times per day equal to 3 + your Wisdom modifier."},{"name":"Lightning Lord","type":"Sp","level":8,"text":"At 8th level, you can call down a number of bolts of lightning per day equal to your cleric level. You can call down as many bolts as you want with a single standard action, but no creature can be the target of more than one bolt and no two targets can be more than 30 feet apart. This ability otherwise functions as call lightning."}],"domainSpells":{"1":"Obscuring Mist","2":"Fog Cloud","3":"Call Lightning","4":"Sleet Storm","5":"Ice Storm","6":"Control Winds","7":"Control Weather","8":"Whirlwind","9":"Storm of Vengeance"},"subdomainNames":["Monsoon","Seasons","Storms"],"subdomains":{"Monsoon":{"grantedPowers":[{"name":"Refreshing Rain","type":"Su","level":8,"text":"At 8th level, as standard action, you can call a brief shower of rain in a 30-foot radius. Creatures in the area are healed of an amount of nonlethal damage equal to double your cleric level and are no longer exhausted, fatigued, nauseated, or sickened. You can use this ability once per day at 8th level, and one additional time per day for every 4 levels beyond 8th."}],"domainSpells":{}},"Seasons":{"grantedPowers":[{"name":"Untouched by the Seasons","type":"Su","level":1,"text":"By touching a creature, you can grant it the benefits of endure elements, which last for 1 hour per cleric level. You can use this ability a number of times per day equal to 3 + your Wisdom modifier."}],"domainSpells":{}},"Storms":{"grantedPowers":[{"name":"Gale Aura","type":"Su","level":6,"text":"At 6th level, as a standard action, you can create a 30-foot aura of gale-like winds that slows the progress of enemies. Creatures in the aura cannot take a 5-foot step. Enemies in the aura treat each square that brings them closer to you as difficult terrain. They can move normally in any other direction. You can use this ability for a number of rounds per day equal to your cleric level. The rounds do not need to be consecutive."}],"domainSpells":{}}}},"Air":{"grantedPowers":[{"name":"Lightning Arc","type":"Sp","level":1,"text":"As a standard action, you can unleash an arc of electricity targeting any foe within 30 feet as a ranged touch attack. This arc of electricity deals 1d6 points of electricity damage + 1 point for every two cleric levels you possess. You can use this ability a number of times per day equal to 3 + your Wisdom modifier."},{"name":"Electricity Resistance","type":"Ex","level":6,"text":"At 6th level, you gain resist electricity 10. This resistance increases to 20 at 12th level. At 20th level, you gain immunity to electricity."}],"domainSpells":{"1":"Obscuring Mist","2":"Wind Wall","3":"Gaseous Form","4":"Air Walk","5":"Control Winds","6":"Chain Lightning","7":"Elemental Body IV (air only)","8":"Whirlwind","9":"Elemental Swarm (air spell only)"},"subdomainNames":["Cloud","Lightning","Wind"],"subdomains":{"Cloud":{"grantedPowers":[{"name":"Thundercloud","type":"Su","level":8,"text":"At 8th level, as a standard action, you can summon a storm cloud. This power functions as fog cloud, except that creatures within the cloud are deafened and take 2d6 points of electricity damage each round from flashes of thunder and lightning. Once created, you can concentrate to move it up to 30 feet each round. You can use this ability a number of rounds per day equal to your cleric level; these rounds need not be consecutive."}],"domainSpells":{}},"Lightning":{"grantedPowers":[{"name":"Lightning Rod","type":"Su","level":8,"text":"As a swift action, when you cast a spell with the electricity descriptor, you may designate a creature within your line of sight. The spell's damage against that target increases by 50%, as though affected by the Empower Spell metamagic feat. This additional damage comes from divine power and is not reduced by electricity resistance, and you take an equal amount of electricity damage immediately after casting the spell. The spell can only deal this additional damage once, even if it could affect the target multiple times. You can use this ability once per day at 8th level, and one additional time per day for every 4 cleric levels you possess beyond 8th."}],"domainSpells":{}},"Wind":{"grantedPowers":[{"name":"Wind Blast","type":"Su","level":1,"text":"As a standard action, you can unleash a blast of air in a 30-foot line. Make a combat maneuver check against each creature in the line, using your caster level as your base attack bonus and your Wisdom modifier in place of your Strength modifier. Treat the result as a bull rush attempt. You can use this ability a number of times per day equal to 3 + your Wisdom modifier."}],"domainSpells":{}}}},"Animal":{"grantedPowers":[{"name":"Speak with Animals","type":"Sp","level":1,"text":"You can speak with animals, as per the speak with animals spell, for a number of rounds per day equal to 3 + your cleric level."},{"name":"Animal Companion","type":"Ex","level":4,"text":"At 4th level, you gain the service of an animal companion. Your effective druid level for this animal companion is equal to your cleric level – 3. (Druids who gain this ability through their nature bond use their druid level – 3 to determine their animal companion's abilities.)"}],"domainSpells":{"1":"Calm Animals","2":"Hold Animal","3":"Dominate Animal","4":"Summon Nature's Ally IV (animals only)","5":"Beast Shape III (animals only)","6":"Antilife Shell","7":"Animal Shapes","8":"Summon Nature's Ally VIII (animals only)","9":"Shapechange"},"subdomainNames":["Feather","Fur","Insect"],"subdomains":{"Feather":{"grantedPowers":[{"name":"Eyes of the Hawk","type":"Ex","level":1,"text":"You gain a racial bonus on Perception checks equal to 1/2 your cleric level (minimum +1). In addition, if you can act during a surprise round, you gain a +2 racial bonus on your Initiative check."}],"domainSpells":{}},"Fur":{"grantedPowers":[{"name":"Predator's Grace","type":"Su","level":1,"text":"As a swift action, you can grant yourself a +10-foot bonus to your base speed for 1 round. This bonus increases by 5 feet for every 5 cleric levels you possess. In addition, you gain low-light vision for 1 round; if you already have low-light vision, your low-light vision range triples for 1 round. You can use this ability a number of times per day equal to 3 + your Wisdom modifier."}],"domainSpells":{}},"Insect":{"grantedPowers":[{"name":"Exoskeleton","type":"Su","level":1,"text":"Domain spells provided by the Insect subdomain affect vermin instead of animals, treating them as though they were not immune to mind-affecting spells. Any of these spells that allow a Will save can instead be negated by the target vermin with a successful Fortitude save with the same DC. As a swift action, you can grow an exoskeleton that grants you a +1 enhancement bonus to your natural armor and 1d4 temporary hit points + 1 for every 2 cleric levels you possess. The natural armor bonus increases by +1 for every 5 cleric levels you possess. The exoskeleton retracts after 1 round, ending its benefits. You can use this ability a number of times per day equal to 3 + your Wisdom modifier."}],"domainSpells":{}}}}};

  function esc(s) {
    return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  }

  function renderPowers(powers) {
    if (!powers || !powers.length) return '';
    return powers.map(p =>
      '<div style="margin:3px 0"><b>' + esc(p.name) + '</b> (' + esc(p.type) + ', ' + esc(p.level) + (p.level==1?'st':(p.level==2?'nd':(p.level==3?'rd':'th'))) + ' level)<br>' +
      '<span style="color:var(--muted,#9ba7b7)">' + esc(p.text) + '</span></div>'
    ).join('');
  }
  function renderSpells(spells) {
    if (!spells) return '';
    const lvls = Object.keys(spells).sort((a,b)=>Number(a)-Number(b));
    if (!lvls.length) return '';
    return '<div style="margin-top:4px;font-size:.68rem;color:var(--muted,#9ba7b7)">' +
      lvls.map(l => l+': '+esc(spells[l])).join(' &middot; ') + '</div>';
  }

  function mount(container, opts) {
    opts = opts || {};
    if (!container || container.querySelector('.domainsBox')) return;
    const box = document.createElement('details');
    box.className = 'sourcesbox domainsBox';
    const summary = document.createElement('summary');
    summary.title = 'Domain reference';
    summary.textContent = 'Domains';
    box.appendChild(summary);

    const panel = document.createElement('div');
    panel.className = 'sourcesPanel domainsPanel';
    panel.style.cssText = 'min-width:300px;max-width:400px';
    const names = Object.keys(DOMAINS).sort((a,b)=>a.localeCompare(b));
    panel.innerHTML = names.map(name => {
      const d = DOMAINS[name];
      const subNames = Object.keys(d.subdomains).sort((a,b)=>a.localeCompare(b));
      const subsHtml = subNames.map(subName => {
        const sd = d.subdomains[subName];
        return '<details class="domainItem" style="margin:2px 0 2px 12px;border-left:2px solid var(--border,#313949);padding-left:6px">' +
          '<summary style="cursor:pointer;font-size:.75rem;padding:2px;color:var(--text,#eef2f7)">' + esc(subName) + ' <span style="color:var(--muted,#9ba7b7);font-size:.65rem">(subdomain)</span></summary>' +
          '<div style="font-size:.7rem;line-height:1.35;margin:2px 0 6px">' + renderPowers(sd.grantedPowers) + renderSpells(sd.domainSpells) + '</div>' +
          '</details>';
      }).join('');
      return '<details class="domainItem" style="margin-bottom:2px">' +
        '<summary style="cursor:pointer;font-size:.78rem;padding:3px 2px;color:var(--text,#eef2f7)">' + esc(name) + '</summary>' +
        '<div style="font-size:.7rem;line-height:1.35;margin:2px 0 6px">' + renderPowers(d.grantedPowers) + renderSpells(d.domainSpells) + '</div>' +
        subsHtml +
        '</details>';
    }).join('');
    box.appendChild(panel);

    if (opts.before) container.insertBefore(box, opts.before);
    else container.appendChild(box);
  }

  global.PFDomains = { mount, DOMAINS };
})(window);
